TN.defSec("gastrointestinal",{"acute-abdominal-pain":{"id":"acute-abdominal-pain","variants":[{"id":"abdpain-unstable","o":{"I":[{"t":"Bedside ultrasound (abdominal aortic aneurysm, free fluid); upright chest or abdominal radiograph for free air; CT with IV contrast when stable"}],"L":[{"t":"Amylase or lipase, β-hCG (women of childbearing age), liver function tests, lactate, coagulation studies, glucose, urinalysis as goal-directed"}],"S":[{"t":"Normal saline or lactated Ringer's solution (most common resuscitation need)"}],"A":[{"t":"Gentamicin 1.5 mg/kg IV plus Metronidazole 1 g IV; or Piperacillin-tazobactam 3.375 g IV","if":"when appropriate for the suspected source"}],"T":[{"t":"Nothing by mouth"},{"t":"Morphine 0.1 mg/kg IV or Hydromorphone 0.2 to 1 mg IV (reversal with naloxone 0.4 to 2 mg SC/IV if necessary)","fl":[{"k":"hi","v":""}]},{"t":"Ondansetron 4 mg IM/IV or Metoclopramide 10 mg IM or slow IV"}],"Co":[{"t":"Surgery (emergent); obstetrics/gynecology for ectopic pregnancy or gynecologic emergencies"}]},"name":"Unstable patient or surgical abdomen","level":"I","imp":"Acute abdomen","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۶۵ ساله با درد شدید شکم، فشار 85/50، نبض 120، شکم سفت و درد با سرفه.","why":"احیا و تشخیص بالینی و مشاوره فوری جراحی."},{"id":"abdpain-stable","o":{"I":[{"t":"Ultrasonography (cholelithiasis, cholecystitis, hydronephrosis, ectopic pregnancy, ovarian pathology, AAA, appendicitis per institution); CT (preferred for mesenteric ischemia, pancreatitis, aortic aneurysm, appendicitis, urolithiasis; IV contrast for vascular lesions and inflammatory conditions, not for urolithiasis; oral contrast for obstruction); plain abdominal radiographs (obstruction, free air)"}],"L":[{"t":"Lipase (or amylase), β-hCG, urinalysis, liver function tests, lactate, glucose, electrolytes, renal function as indicated"}],"T":[{"t":"Nothing by mouth during initial evaluation"},{"t":"Ketorolac 30 mg IV or Ibuprofen 200 to 400 mg PO in renal colic (controversial in other conditions; can mask peritoneal inflammation)","fl":[{"k":"renal","v":"NSAID"}]},{"t":"Morphine 0.1 mg/kg IV or Hydromorphone 0.2 to 1 mg IV","fl":[{"k":"hi","v":""}]},{"t":"Ondansetron 4 mg IM/IV or Metoclopramide 10 mg IM or slow IV"}],"Co":[{"t":"Admission; otherwise 12 to 24 hours follow-up with return precautions","if":"toxic appearance, unclear diagnosis in elderly or immunocompromised, intractable pain or vomiting, altered mental status"}]},"name":"Stable, undifferentiated abdominal pain","level":"II","imp":"Acute abdominal pain","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"زنی ۴۵ ساله با درد شکم ۱۲ ساعته و تهوع؛ فشار طبیعی و بدون پریتونیت.","why":"ارزیابی هدفمند با آزمایش و تصویربرداری؛ مشاهده و معاینه سریال."}],"ch":"35","name":"Acute abdominal pain (undifferentiated)","name_fa":"درد حاد شکم","cc":["abdominal-pain","nausea-vomiting"],"keywords":"abdominal pain, acute abdomen, peritonitis, mesenteric ischemia, Carnett sign, lipase, CT abdomen, ketorolac, morphine, ondansetron, درد شکم","status":"draft","features":["منشأ گوارشی، ادراری‌تناسلی، قلبی‌عروقی، ریوی، عضلانی‌اسکلتی، پوستی، عصبی؛ درد احشایی، جداری یا ارجاعی","ابتدا تهدیدهای فوری را در نظر بگیر؛ زمان شروع، کیفیت، شدت، محل و انتشار، عوامل تشدید/تسکین، دفعات قبلی؛ علائم قلبی‌ریوی و ادراری و سابقه تروما و تاریخچه زنان","پریتونیت: بیمار بی‌حرکت؛ مجموعه rigidity، تندرنس ارجاعی و به‌ویژه cough pain مناسب‌تر از rebound است (rebound کاذب در یک‌چهارم)","Carnett (sit-up test): تندرنس ثابت یا بیشتر در نیمه‌نشسته = درد دیواره شکم","معاینه لگنی در همه زنان پس از بلوغ؛ معاینه رکتال","سالمند، دیابتی و ایمنی‌سرکوب: علائم کم؛ تاکی‌کاردی ممکن است نباشد؛ عدم تب عفونت را رد نمی‌کند؛ علل شایع بالای 50 سال: صفراوی، انسداد روده، دیورتیکولیت، سرطان، فتق؛ ایسکمی مزانتر را در درد نامتناسب با معاینه در > 50 سال در نظر بگیر","تغییر محل: RUQ (صفرا، هپاتیت، آبسه کبد)، LUQ (زخم معده، پانکراتیت، طحال)، RLQ (آپاندیسیت، اکتوپیک، تورشن تخمدان/بیضه، سنگ حالب)، LLQ (دیورتیکولیت سیگموئید)، منتشر (AAA، ایسکمی مزانتر، سوراخ‌شدگی، انسداد)"],"ddx":[{"n":"Leaking / ruptured abdominal aortic aneurysm |","cm":1},{"n":"Mesenteric ischemia |","cm":1},{"n":"Perforated viscus / peritonitis |","cm":1},{"n":"Ectopic pregnancy |","cm":1},{"n":"Bowel obstruction / volvulus |","cm":1},{"n":"Appendicitis |"},{"n":"Pancreatitis / cholecystitis |"},{"n":"Renal colic |"},{"n":"Myocardial ischemia / pneumonia / pulmonary embolism (referred) |"}],"redflags":["ناپایداری همودینامیک، شکم سفت، پریتونیت","سن بالا با درد نامتناسب با معاینه"],"guide":"بیمار ناپایدار ابتدا احیا و تشخیص بالینی و مشاوره فوری جراحی. NPO در ارزیابی اولیه؛ مایع NS یا رینگر لاکتات؛ مسکن با احتیاط (می‌تواند معاینه را بهتر کند)؛ ضدتهوع؛ آنتی‌بیوتیک مناسب منبع. بستری در ظاهر سمی، تشخیص نامشخص در سالمند/ایمنی‌سرکوب، درد یا استفراغ مقاوم، تغییر هوشیاری.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 35: Acute Abdominal Pain, pp. 217–221"},"nausea-vomiting":{"id":"nausea-vomiting","variants":[{"id":"nv-dehydrated","o":{"L":[{"t":"Liver function tests, urinalysis, lipase or amylase; electrolytes and renal function in severe dehydration or prolonged vomiting; pregnancy test in women of childbearing age; drug levels (acetaminophen, salicylate, digoxin) when toxicity suspected","if":"vomiting associated with abdominal pain"}],"S":[{"t":"Normal saline boluses 20 mL/kg IV, repeat as necessary targeting euvolemia (caution in the elderly and compromised LV function)","if":"seriously ill"},{"t":"Oral rehydration solution containing sodium and glucose (e.g., Pedialyte)","if":"mildly dehydrated, tolerating oral"}],"T":[{"t":"Ondansetron 4 to 8 mg IV or ODT (children 0.15 mg/kg) (can be given to pregnant women, category B)"},{"t":"Promethazine 25 mg IM or PR every 4 to 6 hours (children over 2 years 0.25 to 1 mg/kg); Prochlorperazine 5 to 10 mg IM every 6 hours or 25 mg PR every 12 hours; Metoclopramide 10 mg IV/IM every 6 to 8 hours (children 0.1 mg/kg; can be given to pregnant women)","if":"alternatives"},{"t":"Meclizine 25 mg PO every 6 hours","if":"vomiting associated with vertigo"}],"Co":[{"t":"Admission for life-threatening cause, toxic or severely dehydrated patients (infants, elderly), or intolerant of oral fluids after hydration"}]},"name":"Vomiting with dehydration","level":"II","imp":"Nausea and vomiting with dehydration","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله با استفراغ مکرر ۲ روزه، مخاط خشک و نبض 110.","why":"اصلاح مایع و الکترولیت و ضدتهوع."}],"ch":"36","name":"Nausea and vomiting","name_fa":"تهوع و استفراغ","cc":["nausea-vomiting"],"keywords":"vomiting, nausea, ondansetron, promethazine, prochlorperazine, metoclopramide, meclizine, oral rehydration, Mallory-Weiss, تهوع","status":"draft","features":["علل گوارشی و سیستمیک: عصبی، عفونی، قلبی، غدد، کلیه، مامایی، دارویی، سمی، روانی","تاریخچه: شروع، دفعات، محتوا (غذای هضم‌نشده، صفرا، مدفوعی)، علائم همراه (تب، درد، اسهال)، مواجهه غذایی و تماس بیمار","هماتمز بعد از استفراغ شدید غیرخونی: Mallory-Weiss؛ صفرا انسداد خروجی معده را رد می‌کند؛ اتساع و اسکار جراحی یا فتق گیرکرده: انسداد روده کوچک","تب: عفونت یا التهاب؛ درد قفسه: MI؛ سرفه و استفراغ: پنومونی؛ درد کمر/پهلو: آنوریسم یا دایسکشن، پانکراتیت، پیلونفریت، کولیک؛ سردرد: افزایش ICP؛ ورتیگو و نیستاگموس: وستیبولر/CNS؛ بارداری: هیپراِمزیس (سه‌ماهه اول) یا پره‌اکلامپسی (سوم)","دیابت: کتواسیدوز؛ بیماری عروق محیطی: ایسکمی مزانتر؛ لیتیوم یا دیگوکسین: مسمومیت؛ هیپرکالمی و هیپوناترمی: نارسایی آدرنال"],"ddx":[{"n":"Myocardial infarction |","cm":1},{"n":"Intracranial hypertension (SAH, tumor, head injury) |","cm":1},{"n":"Bowel obstruction |","cm":1},{"n":"Diabetic ketoacidosis / adrenal insufficiency |","cm":1},{"n":"Gastroenteritis / appendicitis / cholecystitis |"},{"n":"Pregnancy-related (hyperemesis, preeclampsia) |"},{"n":"Drug or toxin effect |"}],"redflags":["هیپوتانسیون، بی‌حالی، دهیدراسیون شدید","علت تهدیدکننده حیات"],"guide":"اصلاح مایع و الکترولیت و درمان اختصاصی علت تهدیدکننده؛ تحمل مایع خوراکی؛ آنتی‌امتیک در بیمار فعالانه استفراغی با دهیدراسیون. تغذیه سریع از مایعات شفاف به جامد؛ پرهیز از میوه خام، کافئین، لاکتوز و سوربیتول.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 36: Nausea and Vomiting, pp. 222–224"},"acute-diarrhea":{"id":"acute-diarrhea","variants":[{"id":"diarrhea-uncomplicated","o":{"S":[{"t":"Normal saline boluses 500 mL IV in adults (20 mL/kg in children)","if":"seriously ill"},{"t":"Oral rehydrating solution with sodium and glucose (Pedialyte, Gatorade): 30 to 100 mL/kg over the first 4 hours","if":"mild dehydration, not vomiting"}],"T":[{"t":"Once oral fluids tolerated: BRAT diet (bananas, rice, apples, toast); avoid raw fruit, caffeine, lactose and sorbitol products"},{"t":"Loperamide 4 mg initially, then 2 mg after each unformed stool (maximum 16 mg/day)","fl":[{"k":"ci","v":"bloody or suspected inflammatory diarrhea (toxic megacolon in C. difficile, HUS in children with Shiga toxin-producing E. coli)"}]},{"t":"Bismuth subsalicylate 30 mL or 2 tablets every 30 minutes for 8 doses; diphenoxylate and atropine 4 mg four times daily","if":"alternatives"},{"t":"Probiotics are safe and may be beneficial; hand washing; no return to work in the food, day care and health care industries until diarrhea resolves"}]},"name":"Uncomplicated acute diarrhea (viral or self-limited)","level":"III","imp":"Acute diarrhea, gastroenteritis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۰ ساله با اسهال آبکی ۲ روزه، بدون تب یا خون؛ دهیدراسیون خفیف.","why":"بیشتر ویروسی یا خودمحدودند: مایع، رژیم و ضدحرکت در غیرخونی."},{"id":"diarrhea-infectious-antibiotics","o":{"L":[{"t":"Stool studies: culture for Salmonella, Shigella, Campylobacter, E. coli O157:H7; Shiga toxin assay; microscopy or antigen assay for Entamoeba histolytica; ova and parasites (> 7 days, travel, untreated water) with enzyme immunoassay for E. histolytica, Giardia and Cryptosporidium antigen; C. difficile toxin if recent antibiotics or hospitalization"},{"t":"Electrolytes and renal function","if":"extremely dehydrated or toxic"}],"S":[{"t":"Oral or IV rehydration as above"}],"A":[{"t":"Empiric, traveler's diarrhea: Ciprofloxacin 500 mg single dose or 500 mg BID × 3 days; alternative Azithromycin 1000 mg single dose, or Trimethoprim/sulfamethoxazole 160/800 mg single dose or BID × 3 days, or Rifaximin 200 mg TID × 3 days"},{"t":"Empiric, infectious diarrhea: Ciprofloxacin 500 mg BID × 5 days; alternative Trimethoprim/sulfamethoxazole 160/800 mg BID × 5 days"},{"t":"Escherichia coli O157:H7: no antibiotics"},{"t":"Salmonella non-typhi: Ciprofloxacin 750 mg BID × 5 days; alternative Azithromycin 500 mg daily × 7 days"},{"t":"Shigella: Ciprofloxacin 750 mg BID × 3 days; alternative Azithromycin 500 mg daily × 3 days"},{"t":"Cyclospora: Trimethoprim/sulfamethoxazole 160/800 mg BID × 10 days"},{"t":"Giardia: Tinidazole 2 g single dose; alternative Nitazoxanide 500 mg BID × 3 days"},{"t":"Vibrio cholerae: Doxycycline 500 mg single dose or Azithromycin 1 g single dose; alternative Trimethoprim/sulfamethoxazole 160/800 mg BID × 3 days"},{"t":"Entamoeba histolytica: Metronidazole 750 mg TID × 10 days AND paromomycin 10 mg/kg TID × 7 days; alternative Metronidazole AND iodoquinol 650 mg TID × 20 days"},{"t":"Listeria monocytogenes: no antibiotics"}],"T":[{"t":"Antimotility agents only when not bloody or inflammatory (shorten the duration when combined with an antibiotic)"}],"Co":[{"t":"Admission for toxic-appearing patients; consider for extremes of age"}]},"name":"Infectious or traveler's diarrhea (antibiotic therapy)","level":"II","imp":"Acute infectious diarrhea","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۰ ساله بعد از سفر خارجی با اسهال شدید، تب و درد شکم و خون در مدفوع.","why":"بیمار با تب و اسهال خونی یا بیش از 3 روز: کشت مدفوع و درمان آنتی‌بیوتیکی بر اساس پاتوژن."}],"ch":"37","name":"Acute diarrhea (infectious gastroenteritis and traveler's diarrhea)","name_fa":"اسهال حاد","cc":["diarrhea","abdominal-pain","fever"],"keywords":"diarrhea, gastroenteritis, traveler's diarrhea, ciprofloxacin, azithromycin, loperamide, oral rehydration, BRAT diet, norovirus, Shigella, Salmonella, Giardia, cholera, اسهال","status":"draft","features":["≥ 3 مدفوع آبکی در روز؛ چهار مکانیسم: افزایش ترشح (وبا)، کاهش جذب، بار اسمزی، حرکت غیرطبیعی؛ حاد < 3 هفته؛ اغلب عفونی","نوروویروس 50 تا 80٪ اسهال عفونی در آمریکا؛ سفر خارجی با 80٪ احتمال باکتریال (E. coli)","علائم همراه: تب، درد، خون؛ غذاها: دریاچه و رود = Giardia؛ صدف = Vibrio؛ برنج = Bacillus cereus؛ تخم‌مرغ = Salmonella؛ گوشت = Campylobacter/Staph/Yersinia/E. coli/Clostridium؛ سیگواتوکسین: پارستزی و حس معکوس دما","آپاندیسیت تا 20٪ با اسهال؛ معاینه رکتال: خون = التهاب، عفونت یا ایسکمی","کشت مدفوع فقط در دهیدراسیون شدید یا سمی، خون یا چرک، ایمنی‌سرکوب و > 3 روز؛ ova و parasite در > 7 روز یا سفر؛ توکسین C. difficile در بیمار اخیر آنتی‌بیوتیک","HUS با E. coli O157:H7: نارسایی کلیه، ترومبوسیتوپنی، همولیز"],"ddx":[{"n":"Hemolytic uremic syndrome (E. coli O157:H7) |","cm":1},{"n":"C. difficile colitis |","cm":1},{"n":"Mesenteric ischemia / appendicitis / diverticulitis |","cm":1},{"n":"Food poisoning / toxin |"},{"n":"Inflammatory bowel disease |"}],"redflags":["دهیدراسیون شدید، ظاهر سمی، خون در مدفوع، نوزاد یا سالمند"],"guide":"اصلاح مایع و الکترولیت. اسهال همراه آنتی‌بیوتیک اغلب با قطع دارو بهتر می‌شود. ORS: 30–100 mL/kg طی 4 ساعت اول؛ سپس رژیم BRAT؛ پرهیز از میوه خام، کافئین، لاکتوز و سوربیتول. ضدحرکت در اسهال خونی یا مشکوک به التهابی ممنوع (مگاکولون سمی، HUS).","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 37: Disorders Presenting Primarily with Diarrhea, pp. 225–232"},"clostridium-difficile-colitis":{"id":"clostridium-difficile-colitis","variants":[{"id":"cdiff-mild-moderate","o":{"L":[{"t":"Stool C. difficile toxin assay"}],"A":[{"t":"Metronidazole 500 mg orally three times daily for 14 days","if":"mild to moderate, not responding to conservative measures"}],"T":[{"t":"Contact isolation, PPE, hand hygiene with soap and water"},{"t":"Discontinue the offending antibiotic; antidiarrheal agents are controversial; probiotics not useful as an adjunct"},{"t":"First relapse: metronidazole 500 mg orally three times daily for 14 days; second relapse: vancomycin 125 mg orally four times daily for 14 days followed by a four-week taper"}]},"name":"Mild to moderate C. difficile","level":"III","imp":"Clostridium difficile infection, mild to moderate","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۶۵ ساله ۱۰ روز بعد از کلیندامایسین با اسهال آبکی ۸ بار در روز و درد کرامپی خفیف.","why":"قطع آنتی‌بیوتیک مسبب؛ اگر پاسخ نداد مترونیدازول."},{"id":"cdiff-severe","o":{"I":[{"t":"Abdominal x-ray (toxic megacolon: air-filled colon > 6 cm); CT as needed"}],"L":[{"t":"Stool C. difficile toxin; electrolytes, renal function, white blood cell count"}],"S":[{"t":"IV fluids for dehydration"}],"A":[{"t":"Vancomycin 125 mg orally four times daily for 14 days","if":"severe diarrhea, systemic response, or failure of outpatient management"},{"t":"Metronidazole 500 mg IV every 6 hours AND Vancomycin 500 mg orally every 6 hours","if":"pseudomembranous colitis complicated by toxic megacolon"}],"T":[{"t":"Contact isolation, PPE, hand hygiene with soap and water"}],"Co":[{"t":"Surgery (immediate for toxic megacolon or intestinal perforation; rarely emergency colectomy for fulminant colitis)"}]},"name":"Severe C. difficile or toxic megacolon","level":"I","imp":"Severe Clostridium difficile colitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۷۵ ساله با تب 39، لکوسیتوز، درد شدید و اتساع شکم؛ X-ray قطر کولون > 6 cm.","why":"بستری و وانکومایسین خوراکی؛ در مگاکولون سمی ترکیب IV و خوراکی و مشاوره جراحی."}],"ch":"37","name":"Clostridium difficile-associated diarrhea and colitis","name_fa":"اسهال و کولیت ناشی از کلستریدیوم دیفیسیل","cc":["diarrhea","abdominal-pain","fever"],"keywords":"C. difficile, pseudomembranous colitis, toxic megacolon, metronidazole, vancomycin, antibiotic-associated diarrhea","status":"draft","features":["باسیل بی‌هوازی با دو توکسین؛ از اسهال تا کولیت پرده‌دار؛ آنتی‌بیوتیک وسیع‌الطیف (کلیندامایسین، سفالوسپورین، آمپی‌سیلین، آموکسی‌سیلین، فلوروکینولون) فلور روده را تغییر می‌دهد","شایع‌ترین علت اسهال عفونی بستری‌ها؛ حالا در بالغین سالم بدون مواجهه بیمارستانی هم","شروع 7 تا 10 روز بعد از آنتی‌بیوتیک (تا هفته‌ها)؛ اسهال آبکی مخاطی تا بیماری سمی با اسهال شدید، درد کرامپی، تب، لکوسیتوز و دهیدراسیون","تشخیص: توکسین در مدفوع؛ کولونوسکوپی لازم نیست","عود در 20 تا 30٪"],"ddx":[{"n":"Toxic megacolon / perforation |","cm":1},{"n":"Infectious colitis |"},{"n":"Inflammatory bowel disease |"}],"redflags":["مگاکولون سمی، سوراخ‌شدگی، تب با لکوسیتوز و درد شدید"],"guide":"ایزوله تماسی، PPE و شستن دست با آب و صابون (الکل بی‌اثر). خفیف در بیمار سالم: قطع آنتی‌بیوتیک مسبب، تأیید و پایش. متوسط: مترونیدازول خوراکی. شدید یا پاسخ سیستمیک: بستری و وانکومایسین خوراکی. مگاکولون سمی: مترونیدازول IV + وانکومایسین خوراکی و مشاوره فوری جراحی.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 37: Disorders Presenting Primarily with Diarrhea, pp. 225–232"},"crohn-disease":{"id":"crohn-disease","variants":[{"id":"crohn-flare","o":{"I":[{"t":"Abdominal CT (most useful test); plain abdominal x-rays (obstruction, perforation, toxic megacolon)"}],"L":[{"t":"Chemistries and type and cross-match when indicated"}],"S":[{"t":"IV fluid replacement; correct electrolyte abnormalities"}],"T":[{"t":"Parenteral analgesia; bowel rest; nasogastric suction if obstruction, ileus or toxic megacolon"},{"t":"Sulfasalazine 3 to 5 g/day (mild to moderate) or Mesalamine up to 4 g/day"},{"t":"Hydrocortisone IV 300 mg/day; oral prednisone 40 to 60 mg/day as induction","if":"severe disease"},{"t":"6-Mercaptopurine up to 1.5 mg/kg/day or Azathioprine up to 2.5 mg/kg/day (steroid-sparing)"},{"t":"Ciprofloxacin 1 to 1.5 mg/kg/day, Metronidazole 10 to 20 mg/kg/day, or Rifaximin 800 mg twice daily; [fulminant colitis] Piperacillin-tazobactam 4.5 g four times daily IV","if":"perianal disease"},{"t":"Infliximab 5 mg/kg IV, or Adalimumab 160 mg SC","if":"medically resistant moderate to severe"},{"t":"Diarrhea: loperamide 4 to 16 mg/day, diphenoxylate 5 to 20 mg/day, or cholestyramine 4 g one to six times daily"}],"Co":[{"t":"Gastroenterology; surgery (obstruction, hemorrhage, perforation, abscess or fistula, toxic megacolon, perianal disease); admission for fulminant colitis, peritonitis, obstruction, significant hemorrhage, severe dehydration or electrolyte imbalance"}]},"name":"Crohn's disease exacerbation","level":"II","imp":"Crohn's disease flare","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"زنی ۳۰ ساله با کرون و تب، اسهال، درد شکم و کاهش وزن از ۲ هفته قبل.","why":"مایع و مسکن و استراحت روده؛ درمان اختصاصی با نظر گوارش."}],"ch":"37","name":"Crohn's disease (inflammatory bowel disease)","name_fa":"بیماری کرون","cc":["abdominal-pain","diarrhea","fever"],"keywords":"Crohn, IBD, sulfasalazine, mesalamine, hydrocortisone, azathioprine, infliximab, adalimumab, fistula, abscess, toxic megacolon","status":"draft","features":["بیماری مزمن گرانولوماتوز با زخم قطعه‌ای در هر نقطه دهان تا مقعد؛ سیر متغیر با بهبودی و عود","درد شکم، بی‌اشتهایی، اسهال و کاهش وزن؛ عوارض: انسداد، آبسه، فیستول (ایلئوسیگموئید، پوست، واژن)، خونریزی، مگاکولون سمی؛ شقاق و فیستول پریآنال","تا 40٪ تظاهرات خارج‌روده‌ای: آرتریت، اووئیت، سنگ کلیه، اریتم ندوزوم، پیودرما گانگرنوزوم؛ بیماری کبدصفراوی؛ ترومبوآمبولی؛ سوءجذب و آنمی","CT شکم مفیدترین تست؛ X-ray برای انسداد، سوراخ‌شدگی و مگاکولون سمی (> 6 cm)؛ کولونوسکوپی تأیید و گسترش را تعیین می‌کند"],"ddx":[{"n":"Toxic megacolon / perforation / obstruction |","cm":1},{"n":"Ulcerative colitis |"},{"n":"Infectious colitis (Campylobacter, Yersinia) |"},{"n":"Tuberculosis / lymphoma |"},{"n":"Ischemic colitis |"}],"redflags":["کولیت فولمینانت، پریتونیت، انسداد، خونریزی قابل‌توجه، دهیدراسیون شدید"],"guide":"ارزیابی شدت و عوارض؛ CBC، شیمی، type and cross در صورت لزوم. درمان اولیه ED: مایع IV، مسکن تزریقی، استراحت روده، اصلاح الکترولیت و ساکشن NG در انسداد/ایلئوس/مگاکولون. تغییر درمان با مشورت گوارش.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 37: Disorders Presenting Primarily with Diarrhea, pp. 225–232"},"ulcerative-colitis":{"id":"ulcerative-colitis","variants":[{"id":"uc-severe","o":{"I":[{"t":"Abdominal x-ray (toxic megacolon > 6 cm); abdominal CT"}],"L":[{"t":"CBC, albumin, liver function tests, stool studies (ova, parasites, enteric pathogens)"}],"S":[{"t":"IV fluid replacement; correct electrolyte abnormalities"}],"A":[{"t":"Piperacillin-tazobactam 4.5 g every 6 hours IV, OR Ampicillin 2 g every 6 hours + Metronidazole 500 mg every 8 hours + Levofloxacin 750 mg daily"}],"T":[{"t":"Parenteral analgesia; bowel rest; nasogastric suction if obstruction, ileus or toxic megacolon"},{"t":"Hydrocortisone 100 mg every 8 hours, or Methylprednisolone 16 mg every 8 hours, or Prednisolone 30 mg every 12 hours"},{"t":"Infliximab 5 mg/kg IV","if":"fulminant colitis unresponsive to IV corticosteroids"},{"t":"Avoid antidiarrheal agents"}],"Co":[{"t":"Gastroenterology and surgery (significant GI hemorrhage, toxic megacolon, bowel perforation)"}]},"name":"Severe ulcerative colitis (admit)","level":"I","imp":"Severe ulcerative colitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۳۵ ساله با اسهال خونی ۱۲ بار در روز، تب، تاکی‌کاردی و آنمی.","why":"بستری با مایع، استروئید وریدی و آنتی‌بیوتیک؛ مشاوره گوارش و جراحی."},{"id":"uc-mild-moderate","o":{"T":[{"t":"Mild active proctitis and left-sided colitis: Mesalamine suppositories 1000 mg at bedtime or enemas 4 g at bedtime (topical steroid preparations: beclomethasone, hydrocortisone, may be better tolerated)"},{"t":"Oral mesalamine 2.4 to 4 g/day","if":"no response to topical therapy"},{"t":"Prednisone 40 to 60 mg/day orally, tapered slowly after remission","if":"unsuccessful"},{"t":"Infliximab 5 mg/kg IV","if":"steroid-dependent or refractory"},{"t":"Supportive: nutritious diet, rest, iron replenishment, dietary elimination of lactose, bulking agents such as psyllium"}],"Co":[{"t":"Gastroenterology follow-up"}]},"name":"Mild to moderate ulcerative colitis (outpatient)","level":"III","imp":"Ulcerative colitis, mild to moderate","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۰ ساله با پروکتیت خفیف و اسهال خونی ۴ بار در روز.","why":"سرپایی با نظر گوارش: مزالامین موضعی یا خوراکی، سپس پردنیزون."}],"ch":"37","name":"Ulcerative colitis","name_fa":"کولیت اولسراتیو","cc":["diarrhea","abdominal-pain","gi-bleeding"],"keywords":"ulcerative colitis, UC, mesalamine, prednisone, hydrocortisone, infliximab, toxic megacolon, proctitis","status":"draft","features":["بیماری مزمن التهابی زخمی کولون و رکتوم با حملات درد کرامپی، اسهال خونی و تنسموس با بهبودی کامل بین حملات","خفیف (60٪؛ رکتوم): < 4 دفعه در روز بدون علائم سیستمیک؛ متوسط (25٪؛ تا خم طحالی)؛ شدید (پان‌کولیت): دفعات زیاد، کاهش وزن، تب، تاکی‌کاردی، آنمی","عوارض: خونریزی (شایع‌ترین)، آبسه/فیستول، انسداد، سوراخ‌شدگی؛ خطر کارسینوم کولون 10 تا 30 برابر؛ مگاکولون سمی (تب، تاکی‌کاردی، دهیدراسیون، شکم دردناک و متسع؛ > 6 cm)","تظاهرات خارج‌روده‌ای: آرتریت، اسپوندیلیت، اپی‌اسکلریت، اووئیت، پیودرما، اریتم ندوزوم، بیماری کبدصفراوی، ترومبوآمبولی"],"ddx":[{"n":"Toxic megacolon / perforation |","cm":1},{"n":"Crohn's colitis |"},{"n":"Infectious / ischemic / radiation / pseudomembranous colitis |"},{"n":"Sexually acquired proctitis (syphilis, gonorrhea, LGV, HSV) |"}],"redflags":["مگاکولون سمی، پریتونیت، خونریزی"],"guide":"شدید: بستری، مایع، مسکن تزریقی، استراحت روده و ساکشن NG در انسداد/ایلئوس/مگاکولون؛ مشاوره گوارش و جراحی. خفیف تا متوسط سرپایی با نظر گوارش. ضداسهال ممکن است مگاکولون ایجاد کند: ممنوع.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 37: Disorders Presenting Primarily with Diarrhea, pp. 225–232"},"constipation":{"id":"constipation","variants":[{"id":"constipation-functional","o":{"I":[{"t":"Flat and erect abdominal films; CT abdomen and pelvis with contrast for organic causes","if":"obstruction or pseudo-obstruction suspected, or to assess stool burden"}],"L":[{"t":"CBC (anemia), TSH (hypothyroidism), electrolytes (hypokalemia, hypercalcemia)","if":"by suspicion"}],"T":[{"t":"Fluids 1.5 L/d, fiber 10 g/d, exercise; fiber as bran 1 cup/d or psyllium 1 tsp three times a day"},{"t":"Docusate sodium 100 mg daily or twice a day; or docusate sodium/sennosides 1 to 2 tablets PO daily or twice daily"},{"t":"Bisacodyl 10 mg PR three times daily (adults or children)","if":"alternatively"},{"t":"Milk of magnesia 15 to 30 mL PO once or twice a day, or Magnesium citrate 240 mL PO once","if":"no renal failure"},{"t":"Lactulose or sorbitol 15 to 30 mL PO once or twice a day; polyethylene glycol 17 g PO","if":"hyperosmolar"},{"t":"Glycerin rectal suppositories; mineral oil (age 5 to 11 years 5 to 15 mL PO daily; age > 12 years 15 to 45 mL PO daily)","if":"children"}]},"name":"Functional constipation","level":"III","imp":"Constipation","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۵۰ ساله با یبوست مزمن، مدفوع سفت و کم‌تحرکی؛ بدون علائم هشدار.","why":"رژیم و ورزش و ملین ملایم؛ آزمایش در شک ارگانیک."},{"id":"constipation-impaction","o":{"T":[{"t":"Manual disimpaction with local anesthetic lubricant and parenteral analgesia or sedation as needed (transvaginal pressure in female patients may assist)"},{"t":"Enemas after disimpaction: soapsuds 1500 mL PR or mineral oil 100 to 150 mL PR (avoid local trauma and rectal perforation)"},{"t":"Regimen of diet, exercise and medication to reestablish fecal flow"},{"t":"Methylnaltrexone 0.15 mg/kg subcutaneously (maximum dose 12 mg)","if":"palliative care, chronic opioid use or abuse, other measures unsuccessful"}],"Co":[{"t":"Surgical evaluation and hospitalization (organic constipation due to obstruction)"}]},"name":"Fecal impaction","level":"II","imp":"Fecal impaction","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۷۵ ساله با یبوست چند روزه، درد رکتال و ترشح مایع؛ معاینه رکتال ایمپکشن.","why":"خارج‌کردن دستی ایمپکشن پایه درمان است؛ سپس تنقیه و رژیم."}],"ch":"38","name":"Constipation (functional, fecal impaction, opioid-induced)","name_fa":"یبوست","cc":["abdominal-pain","anorectal"],"keywords":"constipation, fecal impaction, disimpaction, enema, lactulose, bisacodyl, polyethylene glycol, methylnaltrexone, opioid-induced, یبوست","status":"draft","features":["≥ 2 مورد: زور زدن، مدفوع سفت، تخلیه ناکامل، < 3 دفع در هفته؛ مزمن: علائم 12 هفته در 12 ماه گذشته","عملکردی: تغییر دارو یا مکمل، کاهش مایع یا فیبر، تغییر فعالیت؛ ارگانیک: شروع حاد، کاهش وزن، خونریزی رکتال/ملنا، تهوع/استفراغ، عدم دفع گاز، تب، درد رکتال، تغییر قطر مدفوع (اولویت: انسداد و کارسینوم)","اسهال ممکن است همراه باشد (مایع از کنار انسداد/ایمپکشن)","معاینه: فتق، توده، آسیت؛ صداهای روده کم در حرکت کند و زیاد در انسداد؛ معاینه رکتال: تون، توده، جسم خارجی، هموروئید، آبسه، ایمپکشن، شقاق و خون","علل حاد: تومور، تنگی، فتق، چسبندگی، ولولوس، دارو (اپیوئید، ضدروان‌پریشی، آنتی‌کولینرژیک)، آنال دردناک؛ مزمن: نوروپاتی، پارکینسون، هیپوتیروئیدی، هیپرپاراتیروئیدی، دیابت، اختلال الکترولیت، آمیلوئیدوز/اسکلرودرمی، سرب و آهن"],"ddx":[{"n":"Bowel obstruction |","cm":1},{"n":"Colon carcinoma |","cm":1},{"n":"Fecal impaction / pseudo-obstruction |"},{"n":"Hypothyroidism / hypercalcemia / hypokalemia |"},{"n":"Medication effect (opioids, anticholinergics) |"}],"redflags":["شروع حاد، کاهش وزن، آنمی، خونریزی رکتال، تغییر قطر مدفوع، عدم دفع گاز"],"guide":"مهم‌ترین نسخه: مایع (1.5 L/d)، فیبر (10 g/d) و ورزش. ایمپکشن: خارج کردن دستی با بی‌حسی موضعی و مسکن/آرام‌بخش؛ سپس تنقیه و رژیم. موارد ارگانیک با انسداد: بستری و ارزیابی جراحی.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 38: Acute and Chronic Constipation, pp. 233–236"},"upper-gi-bleeding":{"id":"upper-gi-bleeding","variants":[{"id":"gib-upper-active","o":{"L":[{"t":"Type and crossmatch; CBC, electrolytes, BUN, creatinine, glucose, coagulation studies, liver function tests"}],"S":[{"t":"Isotonic crystalloid (normal saline or Ringer lactate) for immediate volume replacement"}],"T":[{"t":"Oxygen; large-bore IV catheters; continuous monitoring"},{"t":"Transfuse blood if active bleeding continues and perfusion does not improve after 2 L of crystalloid (lower threshold in the elderly); replace coagulation factors as needed"},{"t":"Nasogastric tube; [if bright red blood or clots] gentle gastric lavage"},{"t":"Pantoprazole 80 mg IV bolus followed by an infusion of 8 mg/h","if":"nonvariceal bleeding from peptic ulcer disease"},{"t":"Octreotide 25 to 50 μg IV bolus followed by 25 to 50 μg/h IV infusion","if":"upper GI bleeding","fl":[{"k":"hi","v":""}]},{"t":"Balloon tamponade with Sengstaken-Blakemore tube or variants","if":"adjunct or temporizing; rarely used due to complications"}],"Co":[{"t":"Gastroenterology (early therapeutic endoscopy) and surgery (uncontrolled bleeding; emergent surgery if no response to pharmacologic and endoscopic treatment); admission"}]},"name":"Significant upper GI bleeding","level":"I","imp":"Upper gastrointestinal bleeding","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۶۰ ساله با هماتمز و ملنا، فشار 85/50، نبض 120 و سابقه مصرف NSAID.","why":"خونریزی قابل‌توجه: احیا با کریستالوئید و خون در صورت نیاز، PPI، اندوسکوپی زودهنگام و بستری."},{"id":"gib-lower","o":{"L":[{"t":"Type and crossmatch; CBC, electrolytes, BUN, creatinine, glucose, coagulation studies"}],"S":[{"t":"Isotonic crystalloid as needed"}],"T":[{"t":"Oxygen; large-bore IV; monitor; rectal examination"},{"t":"Nasogastric tube to exclude upper GI bleeding in disguise"},{"t":"Angiography, scintigraphy or endoscopy depending on resources and consultant preference"}],"Co":[{"t":"Gastroenterology / surgery; admission"}]},"name":"Lower GI bleeding","level":"II","imp":"Lower gastrointestinal bleeding","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۷۰ ساله با هماتوشزی ماروونی ۳ بار؛ فشار 110/70 و نبض 95.","why":"بیشتر خودبه‌خود متوقف می‌شود؛ تثبیت و اندوسکوپی یا آنژیوگرافی بر اساس منابع."}],"ch":"39","name":"Gastrointestinal bleeding (upper and lower)","name_fa":"خونریزی گوارشی","cc":["gi-bleeding","weakness","hypotension-shock","syncope"],"keywords":"GI bleeding, hematemesis, melena, hematochezia, varices, pantoprazole, octreotide, Sengstaken-Blakemore, endoscopy, transfusion, خونریزی گوارشی","status":"draft","features":["باید تا اثبات خلاف تهدیدکننده حیات تلقی شود؛ فوقانی (پروگزیمال به لیگامان Treitz) شایع‌تر: PUD، گاستریت/ازوفاژیت اروزیو، واریس مری/معده، Mallory-Weiss؛ تحتانی: دیورتیکولار، کولیت، پولیپ، بدخیمی","هماتمز یا قهوه‌ای: فوقانی؛ ملنا: پروگزیمال به کولون راست؛ هماتوشزی: دیستال، ولی 10٪ هماتوشزی با خونریزی فوقانی","کاهش وزن و تغییر عادات روده: بدخیمی؛ استفراغ و عق بعد از هماتمز: Mallory-Weiss؛ دارو و الکل: PUD، گاستریت، واریس؛ آنژیوم عنکبوتی، اریتم کف دست، ایکتر: بیماری کبدی","آهن یا بیسموت ملنا را شبیه می‌کنند و چغندر هماتوشزی؛ گایاک منفی است","تشخیص: بررسی گوش و حلق (خون بلعیده‌شده)، NG (منفی کاذب ممکن)، معاینه رکتال؛ هماتوکریت اولیه بازتاب‌دهنده خونریزی نیست؛ خونریزی فوقانی BUN را بالا می‌برد","خونریزی تحتانی: آنژیوگرافی، سینتی‌گرافی یا اندوسکوپی؛ 80٪ خودبه‌خود متوقف می‌شود"],"ddx":[{"n":"Esophageal or gastric varices |","cm":1},{"n":"Peptic ulcer disease |","cm":1},{"n":"Mallory-Weiss tear |"},{"n":"Diverticular bleeding / colitis / polyps / malignancy |"},{"n":"Aortoenteric fistula |"}],"redflags":["هیپوتانسیون، تاکی‌کاردی، سنکوپ، آنژین، گیجی","پیشرفت علی‌رغم 2 L کریستالوئید"],"guide":"اولویت: ABC، اکسیژن، IV بزرگ و مانیتور. حجم: کریستالوئید ایزوتونیک؛ تصمیم ترانسفوزیون بر اساس شواهد بالینی (ادامه خونریزی فعال و عدم بهبود پرفیوژن بعد از 2 L) نه هماتوکریت؛ آستانه پایین‌تر در سالمند. NG در اغلب موارد مهم؛ اندوسکوپی درمانی زودهنگام در خونریزی فوقانی قابل‌توجه.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 39: Gastrointestinal Bleeding, pp. 237–238"},"esophageal-dysphagia-gerd":{"id":"esophageal-dysphagia-gerd","variants":[{"id":"gerd-main","o":{"I":[{"t":"AP and lateral neck and chest x-rays (dysphagia); barium swallow (often the first test) as outpatient"}],"T":[{"t":"Mild disease: H2 blocker (ranitidine 150 mg PO twice daily) or proton pump inhibitor (omeprazole 20 to 40 mg PO daily)"},{"t":"Prokinetic drugs (metoclopramide 10 to 15 mg PO 30 minutes before meals and at bedtime; reduce dose by 50% in the elderly)"},{"t":"Avoid ethanol, caffeine, nicotine, chocolate, fatty foods; head of the bed elevated 30°; no eating within 3 hours of bedtime"},{"t":"Withdraw the offending agent","if":"medication-induced esophagitis"},{"t":"ECG and chest radiograph in ambiguous presentations (cautious approach given ischemic disease)"}]},"name":"GERD or esophagitis","level":"III","imp":"Gastroesophageal reflux disease","cond":"Urgent","act":"RBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۴۰ ساله با سوزش سردل بعد از غذا و بهبود با آنتی‌اسید؛ ECG و CXR طبیعی.","why":"پس از رد ایسکمی درمان تجربی با H2 بلوکر یا PPI."}],"ch":"40","name":"Dysphagia, GERD and esophagitis","name_fa":"دیسفاژی، ریفلاکس و ازوفاژیت","cc":["chest-pain","ent"],"keywords":"dysphagia, GERD, heartburn, esophagitis, ranitidine, omeprazole, metoclopramide, Barrett, pill esophagitis","status":"draft","features":["دیسفاژی: انتقالی (اوروفارنژیال) یا انتقالی (مری)؛ جامد پیشرونده به مایع: مکانیکی؛ جامد و مایع هر دو: اختلال حرکتی؛ ممکن است خطر آسپیراسیون","علل ساختاری: نئوپلاسم (سنگفرشی)، تنگی، web، Schatzki، دیورتیکول؛ حرکتی: عصبی‌عضلانی (CVA شایع‌ترین)، آشالازی، اسپاسم منتشر","تمایز درد مری از ایسکمی قلب در ED دشوار یا ناممکن است: پیش‌فرض درد قلبی تا اثبات خلاف","GERD: سوزش سردل، ارتباط با غذا و وضعیت، بهبود با آنتی‌اسید؛ ارائه غیرتیپیک: علائم ریوی (آسم)، گوش و حلق، فرسایش دندان، لارنژیت، سینوزیت، سرفه؛ عوارض: تنگی، ازوفاژیت، Barrett","ازوفاژیت: التهابی (GERD، NSAID، KCl، داکسی‌سایکلین، تتراسایکلین، کلیندامایسین) یا عفونی در ایمنی‌سرکوب (Candida شایع‌ترین، HSV، CMV)"],"ddx":[{"n":"Acute coronary syndrome (default assumption) |","cm":1},{"n":"Esophageal perforation |","cm":1},{"n":"Peptic ulcer disease |"},{"n":"Esophageal spasm / achalasia |"}],"redflags":["ناتوانی در بلع ترشحات (خطر راه هوایی)، درد قفسه با ریسک قلبی"],"guide":"دیسفاژی اغلب سرپایی ارزیابی می‌شود (باریم، ویدئوازوفاگوگرافی، مانومتری، ازوفاگوسکوپی). GERD: درمان سرپایی با کاهش اسید، افزایش حرکت و حذف عوامل خطر. ازوفاژیت دارویی: قطع داروی مسبب.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 40: Esophageal Emergencies, pp. 239–243"},"esophageal-perforation":{"id":"esophageal-perforation","variants":[{"id":"esoph-perf-main","o":{"I":[{"t":"Esophagram or emergency endoscopy (confirm); chest radiograph (pleural effusion, pneumothorax, pneumomediastinum)"}],"S":[{"t":"Fluid resuscitation"}],"A":[{"t":"Piperacillin/tazobactam 3.375 g IV (single-drug coverage)"},{"t":"Cefotaxime 2 g IV or Ceftriaxone 2 g IV PLUS Clindamycin 600 mg IV or Metronidazole 15 mg/kg IV once, then 7.5 mg/kg q6h (maximum 1 g/dose)","if":"or double coverage"}],"Co":[{"t":"Emergent surgical consultation; hospitalization"}]},"name":"Esophageal perforation","level":"I","imp":"Esophageal perforation","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۵۰ ساله بعد از استفراغ شدید با درد شدید قفسه، تب، فشار 90/60 و آمفیزم زیرجلدی گردن.","why":"تأخیر کشنده است: مایع، آنتی‌بیوتیک و جراحی اورژانس."}],"ch":"40","name":"Esophageal perforation","name_fa":"سوراخ‌شدگی مری","cc":["chest-pain","abdominal-pain"],"keywords":"Boerhaave, esophageal rupture, mediastinitis, Hamman crunch, esophagram, piperacillin-tazobactam","status":"draft","features":["ایاتروژنیک شایع‌ترین؛ دیگر: افزایش فشار داخل مری (Boerhaave)، تروما، جسم خارجی، عفونت، تومور، آئورت؛ مرگ‌ومیر بالا","درد حاد، شدید و بی‌امان، منتشر قفسه، گردن و شکم؛ انتشار به پشت و شانه؛ بلع تشدید می‌کند","زودهنگام: سفتی شکم با افت فشار و تب؛ تاکی‌کاردی و تاکی‌پنه؛ آمفیزم مدیاستن دیر؛ Hamman crunch؛ افیوژن پلور در 50٪ سوراخ‌شدگی داخل قفسه","CXR می‌تواند پیشنهاد کند؛ ازوفاگرام یا اندوسکوپی اورژانس برای تأیید (CT محدودیت دارد)"],"ddx":[{"n":"Acute myocardial infarction |","cm":1},{"n":"Pulmonary embolism |","cm":1},{"n":"Acute abdomen |","cm":1},{"n":"Aortic dissection |"}],"redflags":["هر مشکوک: درمان فوری و جراحی"],"guide":"مدیریت سریع و تهاجمی. مایع، آنتی‌بیوتیک وسیع‌الطیف برای هوازی و بی‌هوازی؛ مشاوره اورژانس جراحی؛ همه بستری.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 40: Esophageal Emergencies, pp. 239–243"},"esophageal-foreign-body":{"id":"esophageal-foreign-body","variants":[{"id":"fb-coin","o":{"I":[{"t":"Radiographs of all children suspected of swallowing coins (AP and lateral to distinguish esophagus from trachea); CT for nonradiopaque objects"}],"T":[{"t":"Coins lodged in the esophagus should be removed by endoscopy (Foley balloon catheter under fluoroscopy by experienced hands: complications include aspiration, airway compromise, mucosal laceration)"},{"t":"Coins in the stomach almost always pass spontaneously"}]},"name":"Coin ingestion","level":"II","imp":"Esophageal coin","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"کودکی ۲ ساله که سکه بلعیده؛ بزاق ریزش و امتناع از غذا.","why":"گرافی برای تعیین محل؛ سکه مری باید با اندوسکوپی برداشته شود."},{"id":"fb-button-battery","o":{"I":[{"t":"Radiographs to locate the battery; repeat x-ray at 48 hours to ensure passage through the pylorus (battery beyond the esophagus)"}],"T":[{"t":"Resuscitate as needed"},{"t":"Emergency endoscopy if lodged in the esophagus; Foley balloon catheter technique may be considered if reliable history of ingestion ≤ 2 hours"},{"t":"Batteries past the esophagus: expectant management with 24-hour follow-up examination"},{"t":"National Button Battery Ingestion Hotline 202-625-3333 (24 hours, 7 days a week)"}],"Co":[{"t":"Surgery if symptoms or signs of GI tract injury"}]},"name":"Button battery ingestion","level":"I","imp":"Esophageal button battery","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","o2":"O2 therapy: if SpO2 < 94%, nasal cannula or face mask with flow by age and weight","sc":"کودکی ۳ ساله که باتری دکمه‌ای بلعیده و استفراغ دارد؛ گرافی باتری در مری.","why":"باتری در مری اورژانس واقعی است و باید فوراً برداشته شود (نکروز ظرف 6 ساعت)."},{"id":"fb-food-sharp-narcotic","o":{"I":[{"t":"Plain films for radiopaque objects (narcotic packets often visible on plain x-ray); CT for nonradiopaque objects"}],"T":[{"t":"Food impaction: complete esophageal obstruction needs emergency endoscopy; uncomplicated impaction may be treated expectantly but not > 12 to 24 hours; proteolytic enzymes (papain meat tenderizer) are contraindicated; Glucagon 1 to 2 mg for adults may be attempted but success rates are poor"},{"t":"Sharp objects in the esophagus, stomach or duodenum: immediate removal by endoscopy; if distal to the duodenum and asymptomatic, daily plain films; consider surgical removal if 3 days without passage"},{"t":"Narcotic packets (body packer): endoscopy is contraindicated (risk of fatal rupture); observation until the packet reaches the rectum; whole-bowel irrigation may aid removal"},{"t":"Indirect or fiberoptic laryngoscopy for very proximal objects in stable patients"}],"Co":[{"t":"Surgery (worrisome distal foreign bodies; symptoms or signs of intestinal injury: pain, emesis, fever, GI bleeding)"}]},"name":"Food impaction, sharp object, or narcotic packets","level":"II","imp":"Esophageal foreign body / food impaction","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"none","sc":"مردی ۶۰ ساله که تکه گوشت بلعیده و نمی‌تواند بزاق را ببلعد؛ یا مردی با بسته‌های مواد مخدر ببلعیده (body packer).","why":"انسداد کامل مری با اندوسکوپی اورژانس؛ body packer اندوسکوپی ممنوع."}],"ch":"40","name":"Swallowed foreign body and food impaction (esophageal)","name_fa":"جسم خارجی مری و گیرکردن غذا","cc":["ent","chest-pain","pediatric-gi"],"keywords":"foreign body, coin ingestion, button battery, food impaction, sharp object, body packer, glucagon, endoscopy, Foley catheter","status":"draft","features":["کودکان 18 تا 48 ماه و بیماران روانی؛ سکه، اسباب‌بازی و مداد رنگی در مری پروگزیمال؛ بالغین: بیشتر دیستال","پس از عبور از پیلور معمولاً از دستگاه عبور می‌کند؛ گیر کردن دیستال به پیلور: نامنظم، لبه تیز، پهن (> 2.5 cm) یا بلند (> 6 cm)","علائم: درد پشت جناغ، دیسفاژی، سرفه، خفگی، استفراغ، آسپیراسیون، ناتوانی در بلع ترشحات؛ کودکان: امتناع از غذا، استفراغ، استریدور، بزاق ریزش","سکه در مری در گرافی AP صورت گرد را نشان می‌دهد (در نای در لترال)","باتری دکمه‌ای: اورژانس واقعی؛ پرفوراسیون ظرف 6 ساعت"],"ddx":[{"n":"Button battery in the esophagus |","cm":1},{"n":"Airway compromise |","cm":1},{"n":"Esophageal stricture / underlying disease (adults) |"}],"redflags":["ناتوانی در بلع ترشحات، خطر راه هوایی، باتری دکمه‌ای یا جسم تیز"],"guide":"بیمار در وضعیت بحرانی: احیا استاندارد؛ اندوسکوپی اورژانس در انسداد کامل دیستال مری با تجمع ترشحات. ادمیشن عموماً لازم نیست اگر اندوسکوپی ساده بود. غذا: انسداد کامل = اندوسکوپی فوری؛ بدون عارضه تا 12–24 ساعت؛ آنزیم‌های پروتئولیتیک (پاپایین) ممنوع؛ گلوکاگون 1–2 mg ممکن است با موفقیت کم.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 40: Esophageal Emergencies, pp. 239–243"},"peptic-ulcer-gastritis":{"id":"peptic-ulcer-gastritis","variants":[{"id":"pud-uncomplicated","o":{"L":[{"t":"CBC (normal CBC rules out chronic bleeding), liver enzymes, lipase; ECG and troponin if myocardial ischemia suspected","if":"to exclude complications"}],"T":[{"t":"PPI 30 to 60 minutes before a meal: omeprazole 20 to 40 mg daily; esomeprazole 20 to 40 mg daily; lansoprazole 15 to 30 mg daily; pantoprazole 20 to 40 mg daily; rabeprazole 20 mg daily"},{"t":"H2RA: cimetidine 200 to 400 mg twice a day; famotidine 10 to 20 mg twice a day; nizatidine 75 to 150 mg twice a day; ranitidine 75 to 150 mg twice a day","if":"alternatively"},{"t":"Liquid antacid 15 mL, 1 hour after meals and at bedtime, as needed for breakthrough pain"},{"t":"Stop NSAIDs whenever possible"},{"t":"Triple therapy for 14 days: PPI, clarithromycin, and either amoxicillin or metronidazole","if":"H. pylori present; rarely initiated in the ED"}],"Co":[{"t":"Primary care follow-up; endoscopy referral for \"alarm\" features (age > 55, weight loss, early satiety, persistent vomiting, dysphagia, anemia, abdominal mass, jaundice)"}]},"name":"Uncomplicated PUD or gastritis","level":"III","imp":"Peptic ulcer disease","cond":"Urgent","act":"RBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۴۵ ساله با درد سوزشی اپی‌گاستر که با غذا بهتر می‌شود و شب‌ها بیدار می‌کند؛ پایدار با تندرنس خفیف.","why":"PUD ساده: PPI یا H2RA و آنتی‌اسید مایع؛ ارجاع برای اندوسکوپی و آزمایش H. pylori."},{"id":"pud-complicated","o":{"I":[{"t":"Upright x-ray (free air in perforation); abdominal ultrasound as needed"}],"L":[{"t":"CBC, liver enzymes, lipase"}],"A":[{"t":"Broad-spectrum antibiotics","if":"perforation","fl":[{"k":"note","v":"agent and dose not given in this chapter"}]}],"T":[{"t":"Resuscitation as needed","if":"perforation"},{"t":"See gastrointestinal bleeding","if":"bleeding"},{"t":"Resuscitation, nasogastric tube","if":"gastric outlet obstruction"}],"Co":[{"t":"Surgery (immediate for perforation); admission for all complications"}]},"name":"Perforation, bleeding or gastric outlet obstruction","level":"I","imp":"Complicated peptic ulcer disease","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مردی ۶۰ ساله با درد ناگهانی و شدید شکم و شکم سفت (سوراخ‌شدگی) در پس‌زمینه مصرف NSAID.","why":"عارضه دار: احیا، آنتی‌بیوتیک وسیع‌الطیف و مشاوره فوری جراحی؛ خونریزی و انسداد برنامه مخصوص."}],"ch":"41","name":"Peptic ulcer disease and gastritis","name_fa":"زخم پپتیک و گاستریت","cc":["abdominal-pain","nausea-vomiting","gi-bleeding"],"keywords":"PUD, peptic ulcer, gastritis, dyspepsia, H. pylori, PPI, omeprazole, famotidine, antacid, perforation, gastric outlet obstruction, زخم معده","status":"draft","features":["بیماری مزمن با زخم‌های راجعه معده و دوازدهه؛ اغلب به عفونت H. pylori یا NSAID مرتبط؛ گاستریت: التهاب مخاط معده؛ دیس‌پپسی: ناراحتی اپی‌گاستر","درد سوزشی اپی‌گاستر (گاه تیز، کسل‌کننده یا حس «گرسنگی/خالی»)، تسکین با غذا، شیر یا آنتی‌اسید و عود با تخلیه معده؛ بیدار شدن از خواب شبانه؛ سالمندان: بدون درد، تهوع، بی‌اشتهایی، کاهش وزن، خونریزی","تغییر ماهیت درد = عارضه؛ شروع ناگهانی و شدید: سوراخ‌شدگی (سفتی شکم)؛ درد پشت: پانکراتیت از سوراخ‌شدگی خلفی؛ استفراغ، سیری زودرس، کاهش وزن: انسداد خروجی معده یا سرطان؛ هماتمز یا ملنا: خونریزی","تشخیص قطعی: اندوسکوپی؛ علائم هشدار برای سرطان: سن > 55، کاهش وزن، سیری زودرس، استفراغ پایدار، دیسفاژی، آنمی، توده، ایکتر","ایسکمی قلبی ممکن است با درد اپی‌گاستر ظاهر شود (دیابتی و سالمند): ECG و تروپونین"],"ddx":[{"n":"Myocardial ischemia |","cm":1},{"n":"Perforated ulcer |","cm":1},{"n":"Abdominal aortic aneurysm |","cm":1},{"n":"Pancreatitis |"},{"n":"Cholelithiasis / biliary colic |"},{"n":"GERD |"},{"n":"Gastric cancer |"}],"redflags":["شکم سفت، هماتمز یا ملنا، استفراغ مداوم، ضعف و سنکوپ"],"guide":"هدف: بهبود زخم، رفع درد، پیشگیری از عارضه و عود. NSAID قطع شود. PPI زودتر زخم را بهبود می‌دهد؛ 30–60 دقیقه قبل از غذا. H. pylori: درمان سه‌دارویی 14 روز (PPI + کلاریترومایسین + آموکسی‌سیلین یا مترونیدازول) به‌ندرت در ED.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 41: Peptic Ulcer Disease and Gastritis, pp. 244–246"},"acute-pancreatitis":{"id":"acute-pancreatitis","variants":[{"id":"pancreatitis-mild","o":{"I":[{"t":"Abdominal CT (preferred over ultrasound) if the diagnosis is unclear; ultrasound for biliary involvement"}],"L":[{"t":"Lipase (preferred; no benefit to ordering both); CBC; liver studies and alkaline phosphatase (biliary involvement); calcium"}],"S":[{"t":"Aggressive fluid resuscitation with crystalloid IV"}],"T":[{"t":"All patients with nausea and vomiting initially NPO"},{"t":"Ondansetron 4 mg or Prochlorperazine 5 to 10 mg (antiemetic)"},{"t":"Morphine 0.1 mg/kg IV (parenteral analgesia)","fl":[{"k":"hi","v":""}]},{"t":"Oxygen to maintain a pulse oximetry reading of 95%"}],"Co":[{"t":"Outpatient management only if mild, no biliary tract disease, no systemic complications, tolerating clear liquids and oral analgesics in the ED"}]},"name":"Mild pancreatitis","level":"II","imp":"Acute pancreatitis","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مردی ۴۵ ساله با درد اپی‌گاستر تیر به پشت، تهوع و لیپاز 5 برابر؛ علائم حیاتی پایدار.","why":"مایع و ضدتهوع و مسکن؛ بیمار خفیف بدون بیماری صفراوی ممکن است سرپایی با پیگیری."},{"id":"pancreatitis-severe","o":{"I":[{"t":"Abdominal CT"}],"L":[{"t":"Lipase, CBC, liver studies, calcium (persistent hypocalcemia < 7 mg/100 mL), BUN, creatinine, blood gas (hypoxia, metabolic acidosis)"}],"S":[{"t":"Aggressive crystalloid fluid resuscitation; pressors for hypotension not responsive to adequate fluid"}],"A":[{"t":"Imipenem-cilastatin 500 mg IV, or Meropenem 1 g IV, or Ciprofloxacin 400 mg IV and Metronidazole 500 mg IV","if":"infected pseudocyst, abscess or infected peripancreatic fluid"}],"T":[{"t":"Oxygen to maintain 95% saturation; treat respiratory failure aggressively (intubation)"},{"t":"Ondansetron 4 mg or Prochlorperazine 5 to 10 mg; Morphine 0.1 mg/kg IV","fl":[{"k":"hi","v":""}]},{"t":"Bladder catheterization, intensive monitoring, transfusion of blood and blood products as needed; correct symptomatic hypocalcemia"},{"t":"Laparotomy may be indicated for hemorrhage or abscess drainage"}],"Co":[{"t":"Intensive care unit with surgical consultation (dropping hemoglobin, poor urine output, persistent hypotension, hypoxia, acidosis, hypocalcemia); gastroenterology for ERCP and sphincterotomy in gallstone pancreatitis"}]},"name":"Severe or complicated pancreatitis","level":"I","imp":"Severe acute pancreatitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۵۵ ساله الکلی با درد شدید شکم، فشار 80/50، SpO2 88٪ و کراتینین بالا.","why":"نارسایی ارگان: احیای تهاجمی، پرسور، اکسیژن یا اینتوباسیون و ICU؛ آنتی‌بیوتیک در عفونت."}],"ch":"42","name":"Acute pancreatitis","name_fa":"پانکراتیت حاد","cc":["abdominal-pain","nausea-vomiting"],"keywords":"pancreatitis, lipase, amylase, gallstone pancreatitis, ERCP, imipenem, meropenem, pancreatic pseudocyst, پانکراتیت","status":"draft","features":["التهاب پانکراس؛ از التهاب موضعی خفیف تا نارسایی چندارگانی؛ شایع‌ترین علل: سنگ صفرا و الکل؛ دارو (استامینوفن، کاربامازپین، انالاپریل، استروژن، اریترومایسین، فوروزماید، HCTZ، اپیوئید، استروئید، تتراسایکلین، TMP-SMX) یا هیپرلیپیدمی شدید","درد ثابت و «حفاری» میان اپی‌گاستر با انتشار به پشت، بدتر در خوابیده؛ تهوع، استفراغ و اتساع؛ تب خفیف، تاکی‌کاردی و افت فشار؛ پریتونیت دیرهنگام؛ ایلئوس","تشخیص: دو از سه: (1) بالین، (2) لیپاز یا آمیلاز ≥ 2 تا 3 برابر حد بالا، (3) تصویربرداری؛ لیپاز ارجح؛ آمیلاز طبیعی رد نمی‌کند؛ هر دو لازم نیست","ALP بالا: سنگ صفرا؛ پیش‌آگهی بد: هیپوکلسمی پایدار (< 7)، هیپوکسی، افزایش BUN، اسیدوز","CT ارجح بر سونوگرافی (گاز روده)؛ در بالین و آزمایش تیپیک تصویربرداری اورژانس لازم نیست"],"ddx":[{"n":"Acute aortic pathology (aneurysm, dissection) |","cm":1},{"n":"Myocardial ischemia |","cm":1},{"n":"Cholecystitis / biliary colic / ascending cholangitis |"},{"n":"Peptic ulcer disease |"},{"n":"Small bowel obstruction |"},{"n":"Pneumonia / renal colic / hepatitis |"}],"redflags":["شوک مقاوم، نارسایی کلیه، تب، تغییر هوشیاری، نارسایی تنفسی"],"guide":"مایع تهاجمی کریستالوئید؛ NPO؛ ضدتهوع؛ مسکن تزریقی؛ اکسیژن برای SpO2 95٪؛ آنتی‌بیوتیک در کیست کاذب/آبسه/مایع عفونی؛ پرسور برای افت فشار پاسخ‌نده؛ بستری اکثر بیماران. سنگ صفرا: مشاوره گوارش برای ERCP.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 42: Pancreatitis and Cholecystitis, pp. 247–251"},"biliary-disease-cholecystitis":{"id":"biliary-disease-cholecystitis","variants":[{"id":"biliary-colic","o":{"I":[{"t":"Ultrasound of the hepatobiliary tract (initial study of choice)"}],"L":[{"t":"CBC, liver function tests, serum lipase or amylase (exclude pancreatitis)"}],"S":[{"t":"Aggressive fluid resuscitation with crystalloid IV"}],"T":[{"t":"NPO"},{"t":"Ondansetron 4 mg or Prochlorperazine 5 to 10 mg"},{"t":"Morphine 0.1 mg/kg IV; Ketorolac 30 mg IV may also help","fl":[{"k":"hi","v":""},{"k":"renal","v":"NSAID"}]},{"t":"Nasogastric tube to low suction","if":"distended or actively vomiting"},{"t":"Discharge if symptoms abate within 4 to 6 hours and oral hydration maintained; oral opioid analgesics for 24 to 48 hours; timely follow-up with a surgical consultant or primary care physician; return if fever, worsening pain, intractable vomiting, another attack"}]},"name":"Uncomplicated biliary colic","level":"III","imp":"Biliary colic","cond":"Urgent","act":"RBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۴۰ ساله و چاق با درد RUQ بعد از غذای چرب ۲ ساعت پیش، تهوع، بدون تب.","why":"کولیک ساده بدون مشاور درمان می‌شود؛ اگر ظرف 4 تا 6 ساعت بهتر شد ترخیص."},{"id":"cholecystitis-acute","o":{"I":[{"t":"Ultrasound; radionuclide cholescintigraphy (HIDA/DISIDA) if ultrasound fails to establish the diagnosis; CT abdomen when other intra-abdominal processes suspected"}],"L":[{"t":"WBC, bilirubin, alkaline phosphatase, lipase or amylase"}],"S":[{"t":"Aggressive crystalloid fluid resuscitation"}],"A":[{"t":"Cefotaxime or Ceftriaxone 1 g IV every 12 to 24 hours plus Metronidazole 500 mg IV"}],"T":[{"t":"NPO; Ondansetron 4 mg or Prochlorperazine 5 to 10 mg; Morphine 0.1 mg/kg IV; Ketorolac 30 mg IV","fl":[{"k":"hi","v":""}]},{"t":"Nasogastric tube to low suction","if":"distended or vomiting"}],"Co":[{"t":"Surgery (immediate) with hospital admission"}]},"name":"Acute cholecystitis","level":"II","imp":"Acute cholecystitis","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مردی ۵۵ ساله با درد RUQ ۱۰ ساعته، تب 38.5، استفراغ و Murphy مثبت.","why":"آنتی‌بیوتیک زودهنگام و مشاوره فوری جراحی با بستری."},{"id":"cholangitis-ascending","o":{"I":[{"t":"Ultrasound (common bile duct > 5 to 7 mm)"}],"L":[{"t":"WBC, bilirubin and alkaline phosphatase (usually elevated), lipase, blood cultures","fl":[{"k":"note","v":"cultures not stated in the chapter"}]}],"S":[{"t":"Aggressive crystalloid fluid resuscitation; pressors for hypotension not responsive to fluids"}],"A":[{"t":"Ampicillin 0.5 to 1.0 g IV every 6 hours plus Gentamicin 1 to 2 mg/kg IV every 8 hours plus Clindamycin 600 mg IV every 6 hours (or equivalent substitutes: metronidazole for clindamycin; third-generation cephalosporin, piperacillin/tazobactam or a fluoroquinolone for ampicillin)"}],"T":[{"t":"NPO; antiemetic; analgesia as above"}],"Co":[{"t":"Surgery and gastroenterology (urgent endoscopic sphincterotomy of the ampulla of Vater / ERCP); intensive care unit pending surgical treatment"}]},"name":"Ascending cholangitis or sepsis","level":"I","imp":"Ascending cholangitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۷۰ ساله با ایکتر، تب 39.5، درد RUQ، گیجی و فشار 80/50.","why":"تهدید حیات: آنتی‌بیوتیک سه‌گانه، احیا و دکمپرسیون اورژانس مجرای صفرا."}],"ch":"42","name":"Biliary colic, acute cholecystitis, cholangitis","name_fa":"کولیک صفراوی، کولسیستیت حاد و کولانژیت","cc":["abdominal-pain","nausea-vomiting","fever","jaundice"],"keywords":"biliary colic, cholecystitis, Murphy sign, cholangitis, Charcot triad, choledocholithiasis, ceftriaxone, metronidazole, ERCP, ultrasound, HIDA, صفرا","status":"draft","features":["بیشتر ناشی از انسداد کیسه یا مجرای صفرا با سنگ: کولیک صفراوی، کولسیستیت، پانکراتیت سنگی و کولانژیت صعودی","عوامل خطر: سن، جنس مؤنث و پاریتی، چاقی، کاهش وزن سریع یا ناشتایی، فامیلی، دارو، نژاد آسیایی، بیماری مزمن کبد، همولیز (سیکل‌سل)","کولیک: درد اپی‌گاستر یا RUQ ثابت یا متناوب با تهوع/استفراغ و انتشار به شانه راست یا پشت چپ؛ 1 تا 5 ساعت؛ اوج 9 شب تا 4 صبح؛ معاینه بدون پریتونیت","کولسیستیت: درد > 5 ساعت، تب، لرز، تهوع، بی‌اشتهایی، تندرنس RUQ و Murphy (حساس‌ترین یافته)؛ کولسیستیت بدون سنگ در 5 تا 10٪ با سیر تهاجمی‌تر (دیابت، سالمند، تروما/سوختگی، جراحی)","کولانژیت صعودی: انسداد کامل مجرای صفرا با سوپراینفکشن؛ ایکتر، تب، گیجی و شوک؛ تریاد Charcot (تب، ایکتر، RUQ)؛ مرگ‌ومیر بالا","سونوگرافی انتخاب اول (سنگ تا 2 mm، دیواره > 3–5 mm، اتساع > 4 cm، مایع اطراف، Murphy سونوگرافیک؛ PPV 92٪)؛ مجرای مشترک > 5–7 mm: سنگ مجرا؛ HIDA/DISIDA حساسیت 97٪ ویژگی 90٪"],"ddx":[{"n":"Ascending cholangitis |","cm":1},{"n":"Gallstone pancreatitis |","cm":1},{"n":"Acute pancreatitis / peptic ulcer disease |"},{"n":"Hepatitis / myocardial ischemia |"},{"n":"Perforation / diffuse peritonitis |"}],"redflags":["ایکتر، تب، گیجی یا شوک (کولانژیت)، سفتی منتشر شکم (سوراخ‌شدگی)"],"guide":"مایع تهاجمی، NPO، ضدتهوع، مسکن (مورفین ± کتورولاک)، NG در اتساع یا استفراغ مقاوم، آنتی‌بیوتیک زودهنگام در شک به کولسیستیت یا کولانژیت، دکمپرسیون با اسفنکتروتومی اندوسکوپیک در انسداد حاد. کولسیستیت و کولانژیت: مشاوره فوری جراحی و بستری.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 42: Pancreatitis and Cholecystitis, pp. 247–251"},"acute-appendicitis":{"id":"acute-appendicitis","variants":[{"id":"appendicitis-main","o":{"I":[{"t":"CT abdomen (96% sensitive; unenhanced acceptable; no contrast for contrast allergy or renal disease); graded compression ultrasonography first in children and pregnant patients; MRI (no gadolinium in pregnancy or renal disease)"}],"L":[{"t":"CBC, C-reactive protein, urinalysis; pregnancy test in all females of reproductive age"}],"S":[{"t":"IV access and fluids"}],"A":[{"t":"Piperacillin/tazobactam 3.375 g IV, or Ampicillin/sulbactam 3 g IV (consult the surgeon regarding the regimen and timing)"}],"T":[{"t":"Nothing by mouth"},{"t":"Fentanyl 1 to 2 μg/kg IV every 1 to 4 hours, or Morphine 0.1 mg/kg","fl":[{"k":"hi","v":""}]}],"Co":[{"t":"Surgery (before imaging when the diagnosis is clear; appendectomy); admit for observation and serial examinations if unclear (pediatric, geriatric, pregnant, immunocompromised)"}]},"name":"Acute appendicitis","level":"II","imp":"Acute appendicitis","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۲۵ ساله با درد ناف که ۱۲ ساعته به RLQ منتقل شده، بی‌اشتهایی و تب 38؛ rebound مثبت.","why":"تشخیص بالینی با CT در موارد نامشخص؛ NPO، مسکن، آنتی‌بیوتیک و جراحی."}],"ch":"43","name":"Acute appendicitis","name_fa":"آپاندیسیت حاد","cc":["abdominal-pain","nausea-vomiting","fever"],"keywords":"appendicitis, McBurney, Rovsing, psoas sign, obturator sign, CT appendix, graded compression ultrasound, appendectomy, آپاندیسیت","status":"draft","features":["از شایع‌ترین اورژانس‌های جراحی؛ عوارض تشخیص اشتباه: آبسه، عفونت زخم، چسبندگی، انسداد، ناباروری","درد از ناف یا اپی‌گاستر شروع و به RLQ مهاجرت می‌کند؛ بی‌اشتهایی، تهوع و استفراغ (غیراختصاصی)؛ تحریک مثانه یا کولون: دیزوری و تنسموس؛ علامت «bump»؛ کاهش ناگهانی درد: به فکر پارگی باش","نقطه McBurney؛ Rovsing؛ psoas؛ obturator؛ آپاندیس لگنی: تندرنس رکتال؛ رتروسکال: درد پهلو","تب دیررس (به‌ندرت > 39)؛ مفیدترین نشانه تب، سپس rebound و مهاجرت درد","تشخیص عمدتاً بالینی؛ نمره‌های Alvarado و Samuel از قضاوت پزشک مجرب حساسیت کمتر دارند؛ WBC و CRP هر دو طبیعی ارزش غربال منفی دارند؛ تست بارداری در همه زنان؛ UA ممکن است پیوری و هماچوری با تحریک حالب نشان دهد","CT انتخاب (حساسیت 96٪)؛ بدون کنتراست هم قابل‌قبول (92٪/96٪)؛ سونوگرافی فشاری تدریجی اولین انتخاب در کودک و باردار (حساسیت 86٪، PPV 95٪)؛ MRI بدون گادولینیوم در بارداری","سالمند، کودک < 6 سال و باردار: تشخیص اشتباه بیشتر؛ آپاندیسیت شایع‌ترین اورژانس جراحی بارداری"],"ddx":[{"n":"Ectopic pregnancy / ovarian torsion |","cm":1},{"n":"Testicular torsion / renal colic |","cm":1},{"n":"Inflammatory bowel disease / diverticulitis |"},{"n":"Hernia / abscess / volvulus |"},{"n":"Genitourinary infection |"}],"redflags":["پریتونیت، کاهش ناگهانی درد، سن < 6 یا بارداری یا سالمند"],"guide":"مشاوره جراحی پیش از تصویربرداری وقتی تشخیص واضح است؛ NPO، IV و مایع؛ درمان آپاندکتومی؛ آنتی‌بیوتیک قبل از جراحی؛ بیمار با تشخیص نامشخص: بستری مشاهده و معاینه سریال (به‌ویژه کودک، سالمند، باردار، ایمنی‌سرکوب).","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 43: Acute Appendicitis, pp. 252–255"},"diverticulitis":{"id":"diverticulitis","variants":[{"id":"diverticulitis-outpatient","o":{"I":[{"t":"CT scan with IV and oral contrast","if":"new diagnosis or different from past episodes"}],"L":[{"t":"CBC, liver function tests, urinalysis (not diagnostic but exclude other diagnoses)"}],"A":[{"t":"First line: Metronidazole 500 mg PO q6h 4 to 7 days PLUS Ciprofloxacin 750 mg PO BID, OR Levofloxacin 750 mg PO q24h, OR Trimethoprim-sulfamethoxazole 1 tab PO BID"},{"t":"Alternate: Amoxicillin-clavulanate extended release 1000/62.5 mg 2 tabs PO BID; Moxifloxacin 400 mg PO q24h"}],"T":[{"t":"Liquid diet"},{"t":"Follow up with a gastroenterology specialist for colonoscopy in 6 weeks if improved; worsening requires admission"}]},"name":"Uncomplicated diverticulitis (outpatient)","level":"III","imp":"Uncomplicated diverticulitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۵۵ ساله با درد LLQ ۲ روزه، تب 37.8 و سابقه دیورتیکولیت؛ پایدار و تحمل خوراکی.","why":"آنتی‌بیوتیک خوراکی و رژیم مایع؛ پیگیری و کولونوسکوپی در 6 هفته."},{"id":"diverticulitis-inpatient","o":{"I":[{"t":"CT scan (severity and complications: phlegmon, abscess, obstruction, fistula, perforation)"}],"S":[{"t":"Fluid and electrolyte replacement"}],"A":[{"t":"Moderate, first line: Metronidazole 500 mg IV TID PLUS (Ciprofloxacin 400 mg IV BID, OR Levofloxacin 750 mg IV q24h, OR Aztreonam 2 g IV TID, OR Ceftriaxone 1 g IV q24h)"},{"t":"Moderate, alternative: Ertapenem 1 g IV q24h; Piperacillin-tazobactam 4.5 g IV q8h; Moxifloxacin 400 mg IV q24h"},{"t":"Severe, life-threatening, first line: Imipenem 500 mg IV q6h; Meropenem 1 g IV q8h; Piperacillin-tazobactam 4.5 g IV q8h"},{"t":"Severe, alternative: Ampicillin 2 g IV q6h PLUS Metronidazole 500 mg IV q6h PLUS (Ciprofloxacin 400 mg IV q12h OR amikacin, gentamicin or tobramycin); penicillin allergy: Aztreonam 2 g IV q6h PLUS metronidazole 500 mg IV q6h"}],"T":[{"t":"Pain and nausea control"}],"Co":[{"t":"Surgery (consultation and admission)"}]},"name":"Complicated or severe diverticulitis (admit)","level":"I","imp":"Complicated diverticulitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"زنی ۶۸ ساله با درد شدید LLQ، تب 39، پریتونیت موضعی و آبسه در CT.","why":"بستری، آنتی‌بیوتیک وریدی و مشاوره جراحی."}],"ch":"44","name":"Diverticulitis","name_fa":"دیورتیکولیت","cc":["abdominal-pain","fever"],"keywords":"diverticulitis, LLQ pain, metronidazole, ciprofloxacin, levofloxacin, ertapenem, piperacillin-tazobactam, colonoscopy","status":"draft","features":["التهاب یا عفونت دیورتیکول‌های کولون؛ کلاسیک: درد LLQ ثابت و عمقی، تب و لکوسیتوز؛ تغییر اجابت مزاج، تهوع، استفراغ، بی‌اشتهایی؛ علائم ادراری کمتر","سیگموئید زائد، نژاد آسیایی یا راست‌طرفه: درد سوپراپوبیک یا RLQ؛ تب خفیف (بالاتر در پریتونیت یا آبسه)؛ خون مخفی ممکن","تشخیص: بالینی؛ بیمار پایدار با حمله مشابه قبلی نیاز به تست ندارد؛ در تشخیص جدید یا الگوی متفاوت: CT با کنتراست IV و دهانی (حساسیت 97٪ و ویژگی نزدیک 100٪)","عوارض: فلگمون، آبسه، انسداد، فیستول، سوراخ‌شدگی"],"ddx":[{"n":"Acute appendicitis |","cm":1},{"n":"Ischemic colitis / mesenteric infarction |","cm":1},{"n":"Colon cancer |"},{"n":"Inflammatory bowel disease |"},{"n":"Ovarian torsion / ectopic / PID |"}],"redflags":["علائم پریتونیت، آبسه، انسداد یا سوراخ‌شدگی، ایمنی‌سرکوب"],"guide":"مایع و الکترولیت، مسکن و ضدتهوع. غیرعارضه‌دار: آنتی‌بیوتیک خوراکی و رژیم مایع (داده‌های جدید ممکن است آنتی‌بیوتیک را لازم ندانند). کولونوسکوپی ظرف 6 هفته. بستری در ظاهر بیمار، درد یا استفراغ کنترل‌نشده، علائم پریتونیت یا سیستمیک، بیماری همراه یا ایمنی‌سرکوب، موارد عارضه‌دار.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 44: Diverticulitis, pp. 256–258"},"bowel-obstruction-volvulus":{"id":"bowel-obstruction-volvulus","variants":[{"id":"obstruction-mechanical","o":{"I":[{"t":"Flat and upright abdominal radiographs plus upright chest x-ray; CT scanning with IV and oral contrast when possible (partial versus complete, partial SBO versus ileus, strangulated versus simple)"}],"L":[{"t":"CBC, electrolytes, BUN, creatinine, lactate, coagulation profile, type and cross-match"}],"S":[{"t":"Vigorous fluid resuscitation with crystalloids"}],"A":[{"t":"Piperacillin/tazobactam 3.375 g IV every 6 hours, or Ticarcillin-clavulanate 3.1 g IV every 6 hours, or Ampicillin/sulbactam 3.0 g"},{"t":"Cefotaxime 2 g or Ceftriaxone 2 g plus Clindamycin 600 mg or Metronidazole 1 g; or a carbapenem such as Meropenem 1 g IV every 8 hours","if":"or double coverage"}],"T":[{"t":"Decompress with a nasogastric tube (especially if vomiting or distension)"}],"Co":[{"t":"Surgery (prompt consultation; surgical intervention is usually necessary)"}]},"name":"Mechanical obstruction or volvulus","level":"I","imp":"Intestinal obstruction","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مردی ۶۵ ساله با سابقه جراحی شکم، درد کرامپی، استفراغ صفراوی، اتساع و عدم دفع گاز.","why":"مایع، NG، آنتی‌بیوتیک وسیع‌الطیف و مشاوره فوری جراحی."},{"id":"ileus-pseudo-obstruction","o":{"I":[{"t":"Abdominal radiograph / CT"}],"S":[{"t":"Intravenous fluids"}],"T":[{"t":"Observation without surgical intervention when adynamic ileus is suspected"},{"t":"Pseudo-obstruction: colonoscopy is both diagnostic and therapeutic; surgery is not indicated"}]},"name":"Adynamic ileus or pseudo-obstruction (Ogilvie)","level":"II","imp":"Adynamic ileus / pseudo-obstruction","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مردی ۸۰ ساله بستری با اتساع شکم و تحمل نشدن غذا؛ بدون پریتونیت؛ CT بدون نقطه انسداد.","why":"اقدامات محافظه‌کارانه: مایع و مشاهده؛ pseudo-obstruction با کولونوسکوپی."}],"ch":"45","name":"Intestinal obstruction, ileus and volvulus","name_fa":"انسداد روده و ولولوس","cc":["abdominal-pain","nausea-vomiting","anorectal"],"keywords":"small bowel obstruction, SBO, large bowel obstruction, sigmoid volvulus, cecal volvulus, ileus, pseudo-obstruction, Ogilvie, nasogastric tube, strangulation","status":"draft","features":["انسداد مکانیکی یا از دست رفتن پریستالتیسم؛ ایلئوس آدینامیک شایع‌تر و معمولاً خودمحدود","SBO: چسبندگی بعد از جراحی، فتق گیرکرده، بیماری التهابی؛ LBO: سرطان، دیورتیکولیت با تنگی، ولولوس سیگموئید، ایمپکشن مدفوع؛ سیگموئید سالمند با آنتی‌کولینرژیک؛ سکوم در باردار؛ کودکان: اینتوساسپشن؛ pseudo-obstruction (Ogilvie) در سالمند، بستری و TCA","درد کرامپی متناوب پیشرونده، عدم دفع مدفوع/گاز؛ استفراغ صفراوی در انسداد پروگزیمال و مدفوعی در دیستال؛ SBO نسبی هنوز گاز دفع می‌کند؛ اتساع، تندرنس، پریتونیت؛ صداهای روده پرصدا و تیز در SBO مکانیکی و کم یا غایب بعد از ساعت‌ها","وجود مدفوع در رکتوم انسداد را رد نمی‌کند؛ لکوسیتوز > 20,000 یا شیفت چپ: آبسه، گانگرن یا پریتونیت","گرافی ایستاده و خوابیده + CXR ایستاده؛ CT با کنتراست IV و دهانی: انتخاب در ED (نسبی/کامل، SBO/ایلئوس، استرانگوله/ساده)"],"ddx":[{"n":"Strangulated bowel / perforation |","cm":1},{"n":"Sigmoid or cecal volvulus |","cm":1},{"n":"Paralytic ileus / pseudo-obstruction |"},{"n":"Incarcerated hernia |"},{"n":"Intussusception (children) |"}],"redflags":["پریتونیت، لکوسیتوز شدید، اتساع، افت فشار"],"guide":"مایع تهاجمی با کریستالوئید، NG برای دکمپرسیون (به‌ویژه با استفراغ یا اتساع)، آنتی‌بیوتیک قبل از جراحی با طیف وسیع و مشاوره سریع جراحی. در ایلئوس آدینامیک یا تردید: مایع و مشاهده. Pseudo-obstruction: کولونوسکوپی تشخیصی و درمانی؛ جراحی لازم نیست.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 45: Intestinal Obstruction and Volvulus, pp. 259–261"},"hernia":{"id":"hernia","variants":[{"id":"hernia-reducible","o":{"T":[{"t":"Outpatient surgical evaluation and repair; avoid heavy lifting; return if herniation recurs and cannot be reduced promptly; discuss signs of obstruction before discharge"},{"t":"Children with uncomplicated umbilical hernias: discharge and follow with primary care; refer if older than 4 years or hernia greater than 2 cm"}]},"name":"Reducible hernia (adult) and umbilical hernia (child)","level":"III","imp":"Hernia, reducible","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۵۰ ساله با برآمدگی قابل‌برگشت کشاله ران که با زور زدن بیرون می‌زند؛ بدون درد حاد.","why":"فتق قابل‌برگشت: ارجاع سرپایی جراحی؛ آموزش علائم انسداد."},{"id":"hernia-incarcerated","o":{"I":[{"t":"Ultrasonography (operator and habitus dependent; helpful in pediatric and pregnant patients); CT (best radiographic test; Spigelian, obturator)"}],"S":[{"t":"Intravenous fluid resuscitation"}],"A":[{"t":"Cefoxitin 2 g IV or Piperacillin/tazobactam 3.375 g IV","if":"evidence of perforation or strangulation"}],"T":[{"t":"Nothing by mouth; intravenous opioid analgesia"},{"t":"Reduction attempts only without signs of strangulation: NPO, analgesia (procedural sedation in children), Trendelenburg, externally rotate and flex the ipsilateral leg, padded icepack, elongate the hernia neck with one hand, firm steady pressure on the proximal hernia at the fascial defect with the other hand"},{"t":"Infants with successfully reduced inguinal hernias: surgical repair within 24 to 72 hours (one-third redevelop incarceration)"}],"Co":[{"t":"Surgery (emergent consultation and intervention)"}]},"name":"Incarcerated or strangulated hernia","level":"I","imp":"Incarcerated / strangulated hernia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"زنی ۷۰ ساله با فتق فمورال دردناک و غیرقابل‌برگشت، استفراغ و تندرنس شدید.","why":"استرانگوله یا ناموفق در ردکشن: مشاوره اورژانس جراحی."}],"ch":"46","name":"Hernia (reducible, incarcerated, strangulated; adults and children)","name_fa":"فتق","cc":["abdominal-pain","genital-complaint"],"keywords":"inguinal hernia, femoral hernia, ventral hernia, umbilical hernia, incarcerated, strangulated, hernia reduction, فتق","status":"draft","features":["بیرون‌زدگی ارگان از حفره طبیعی؛ شایع‌ترین: اینگوینال، ونترال، فمورال","عوامل: سابقه خانوادگی، نارس بودن، بیضه نزول‌نکرده، افزایش فشار داخل شکم (آسیت، بارداری، COPD)، محل جراحی","قابل‌برگشت؛ گیرکرده (incarcerated: غیرقابل‌برگشت) و استرانگوله (strangulated: اختلال عروقی، اورژانس جراحی؛ درد و تندرنس شدید، سفتی و اریتم)؛ ممکن است به انسداد، گانگرن، سوراخ‌شدگی، پریتونیت و شوک برسد","کودکان: تحریک‌پذیری و تغذیه ضعیف؛ بررسی انسداد","تشخیص عمدتاً با معاینه؛ سونوگرافی در کودک و باردار؛ CT بهترین برای انواع نادر (Spigelian، obturator)","افتراق توده کشاله: تورشن بیضه، تومور، آبسه، هیدروسل، واریکوسل"],"ddx":[{"n":"Testicular torsion |","cm":1},{"n":"Groin abscess / tumor |"},{"n":"Hydrocele / varicocele |"},{"n":"Undescended testis in children |"}],"redflags":["علائم استرانگولاسیون: ردکشن ممنوع"],"guide":"ردکشن اگر علائم استرانگولاسیون وجود دارد انجام نشود (ورود روده مرده به شکم). مراحل: NPO؛ مسکن مناسب (کودکان سدیشن)؛ Trendelenburg؛ چرخش خارجی و فلکسیون پا؛ کیسه یخ؛ گرفتن و کشیدن گردن فتق با یک دست و فشار ثابت با دست دیگر روی نقص فاسیال.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 46: Hernia in Adults and Children, pp. 262–264"},"anorectal-benign":{"id":"anorectal-benign","variants":[{"id":"anorectal-hemorrhoid-fissure","o":{"T":[{"t":"Hot sitz baths for at least 15 minutes, three times per day and after each bowel movement; dry the anus gently but thoroughly afterwards"},{"t":"Topical steroid and topical analgesic (temporary relief)","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Bulk laxative such as psyllium seed compound or stool softener after the acute phase; avoid laxatives that cause liquid stool","why":"liquid stool may cause cryptitis and sepsis"}],"Co":[{"t":"Surgical referral for fissure not healing in 6 weeks after adequate treatment, or for sentinel tag (possible inflammatory bowel disease)"}]},"name":"Hemorrhoids / fissure, stable (outpatient care)","level":"III","imp":"Hemorrhoids / anal fissure","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۵ ساله با درد تیز هنگام اجابت مزاج و کمی خون قرمز روشن روی دستمال؛ علائم حیاتی پایدار.","why":"درمان غیرجراحی: سیتز، فیبر و ضددرد موضعی؛ بیمار سرپایی با پیگیری.","esc":["جراحی فوری: خونریزی ادامه‌دار، گیرکردگی یا استرانگولاسیون، درد غیرقابل کنترل"]},{"id":"anorectal-thrombosed-hemorrhoid","o":{"T":[{"t":"Local anesthesia with a long-acting agent such as 0.5% bupivacaine with epinephrine, then elliptical skin incision over the hemorrhoid and evacuation of the thrombosed clot (clot excision)"},{"t":"Hemostasis with packing and pressure dressing; pressure dressing may be removed after about 6 hours with the first sitz bath"},{"t":"Hot sitz baths for at least 15 minutes, three times per day and after each bowel movement"}],"Co":[{"t":"Surgeon for definitive hemorrhoidectomy"}]},"name":"Thrombosed external hemorrhoid (< 48 hours)","level":"III","imp":"Thrombosed hemorrhoid","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۳۰ ساله با توده بنفش دردناک مقعد از دیروز.","why":"در کمتر از ۴۸ ساعت، خارج‌کردن لخته با بی‌حسی موضعی بهترین تسکین را می‌دهد."},{"id":"anorectal-complicated-hemorrhoid","o":{"T":[{"t":"Analgesia","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Hot sitz baths and gentle drying while awaiting surgery"}],"Co":[{"t":"Surgery for severe intractable pain, continued bleeding, incarceration or strangulation"}]},"name":"Incarcerated / gangrenous / intractably bleeding hemorrhoid","level":"II","imp":"Complicated hemorrhoid (incarceration, strangulation or severe bleeding)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۶۰ ساله با پرولاپس هموروئید غیرقابل جا انداختن، درد شدید و احتباس ادرار.","why":"گیرکردگی، استرانگولاسیون، خونریزی ادامه‌دار یا درد مقاوم نیاز به جراحی دارد؛ NPO برای احتمال عمل."}],"ch":"47","name":"Hemorrhoids, anal fissure, cryptitis, anal tags, pruritus ani","name_fa":"هموروئید، فیشر مقعدی، کریپتیت، زائده پوستی مقعد و خارش مقعد","cc":["anorectal","gi-bleeding"],"keywords":"hemorrhoids, thrombosed hemorrhoid, clot excision, anal fissure, sentinel pile, cryptitis, skin tags, pruritus ani, pinworm, sitz bath, هموروئید, فیشر","status":"draft","features":["هموروئید: احتقان، پرولاپس یا ترومبوز وریدهای هموروئیدی داخلی/خارجی؛ خونریزی بدون درد قرمز روشن روی مدفوع، دستمال یا چکه در توالت؛ ترومبوزه معمولاً دردناک و توده بنفش-آبی","هموروئید بزرگ: پرولاپس خودبه‌خود جا می‌رود یا نیاز به جا انداختن دستی دارد؛ ممکن است گیر کرده و گانگرنه شود؛ ترشح مخاطی و خارش","هموروئید داخلی لمس نمی‌شود و با آنوسکوپ دیده می‌شود (ساعت 2، 5 و 9 در وضعیت prone)؛ علل: یبوست، حاملگی، آسیت، تومور تخمدان، فیبروز پرتویی، افزایش فشار پورت","فیشر مقعدی: پارگی خطی سطحی (اغلب خط وسط خلفی)؛ شایع‌ترین علت خونریزی دردناک رکتوم؛ درد تیز و برنده هنگام اجابت مزاج که بین دفعات کم می‌شود؛ خون قرمز روشن کم؛ در مزمن sentinel pile","فیشر غیر از خط وسط خلفی: Crohn، کولیت اولسراتیو، کارسینوم، AIDS، سل و بیماری‌های آمیزشی را در نظر بگیر","کریپتیت: درد حین دفع و خارش با یا بدون خونریزی؛ کریپت‌های متورم و دردناک با پاپیلای هیپرتروفیک؛ پیامد: آبسه، فیشر، فیستول","زائده پوستی (anal tag) معمولاً بی‌علامت است؛ sentinel tag ممکن است با IBD همراه باشد؛ خارش مقعد در کودکان اغلب کرم‌ریشه (Enterobius) است"],"ddx":[{"n":"Rectal or sigmoid tumor (older than 40 years) |","cm":1},{"n":"Crohn disease / ulcerative colitis (non-midline fissure, sentinel tag) |","cm":1},{"n":"Anorectal abscess / fistula |"},{"n":"Infectious proctitis / sexually transmitted infection |"},{"n":"Rectal prolapse |"}],"redflags":["خونریزی شدید یا ادامه‌دار، گیرکردگی/استرانگولاسیون یا گانگرن، احتباس ادرار یا سپسیس","سن بالای 40 سال با خونریزی رکتوم (تومور را در نظر بگیر)"],"guide":"# هموروئید\nحمام سیتز گرم حداقل ۱۵ دقیقه، سه بار در روز و بعد از هر اجابت مزاج، سپس خشک کردن ملایم. استروئید و بی‌حس‌کننده موضعی موقتاً کمک می‌کند. ملین حجیم‌کننده (psyllium) یا نرم‌کننده مدفوع بعد از فاز حاد؛ ملین‌هایی که مدفوع آبکی می‌دهند ممنوع‌اند (کریپتیت و سپسیس).\n\nهموروئید ترومبوزه حاد کمتر از ۴۸ ساعت: خارج‌کردن لخته (clot excision) با بی‌حسی موضعی طولانی‌اثر مثل bupivacaine 0.5٪ با اپی‌نفرین، برش بیضی‌شکل و تخلیه لخته؛ هموستاز با پک و پانسمان فشاری؛ پانسمان بعد از حدود ۶ ساعت با اولین حمام سیتز برداشته می‌شود؛ ارجاع به جراح برای هموروئیدکتومی قطعی.\n\nجراحی: درد شدید و مقاوم، خونریزی ادامه‌دار، گیرکردگی یا استرانگولاسیون.\n\n# فیشر و کریپتیت\nهدف: رفع اسپاسم اسفنکتر و درد و پیشگیری از تنگی؛ حمام سیتز، فیبر (سبوس)، بی‌حس‌کننده یا استروئید موضعی؛ اگر بعد از ۶ هفته درمان کافی بهبود نیافت، برداشتن جراحی. کریپتیت: ملین حجیم‌کننده، فیبر بیشتر، سیتز و شست‌وی گرم رکتوم؛ موارد مقاوم جراحی.\n\n# خارش مقعد\nفیبر بیشتر، حمام سیتز، آنتی‌هیستامین، پماد اکسید روی یا هیدروکورتیزون 1٪؛ درمان علت زمینه‌ای؛ مقاوم: ارجاع به پروکتولوژیست یا پوست.","pearls":["خونریزی بدون درد قرمز روشن = هموروئید؛ خونریزی دردناک = فیشر تا خلاف آن ثابت شود.","لزوم معاینه دیجیتال رکتوم و سپس آنوسکوپی در پوزیشن لترال چپ."],"section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 47: Anorectal Disorders, pp. 265–272"},"anorectal-abscess-fistula":{"id":"anorectal-abscess-fistula","variants":[{"id":"anorectal-simple-perianal-abscess","o":{"T":[{"t":"Local and systemic analgesia, then incision and drainage of the abscess (cruciate incision over the abscess, excise the \"dog ears\"); packing usually not required"},{"t":"Sitz baths starting the next day"}],"Co":[{"t":"Surgeon follow-up"}]},"name":"Simple isolated perianal abscess (no systemic illness)","level":"III","imp":"Perianal abscess","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۴۰ ساله با درد ضرباندار و توده دردناک کنار مقعد؛ بدون تب.","why":"آبسه ساده پری‌آنال فقط با برش و تخلیه در ED درمان می‌شود؛ آنتی‌بیوتیک لازم نیست."},{"id":"anorectal-complicated-abscess-fistula","o":{"I":[{"t":"Ultrasonography with a 7 MHz endoprobe enhanced with 3% hydrogen peroxide may aid diagnosis of fistula in ano"}],"T":[{"t":"Analgesics and antipyretics","fl":[{"k":"note","v":"drugs and doses not given in the book"}]},{"t":"Sitz baths and local cleaning until surgery"}],"A":[{"t":"Ciprofloxacin 750 mg twice daily and Metronidazole 500 mg four times daily for 7 days","if":"non-ill-appearing patient with fistula in ano"},{"t":"Antibiotics","if":"systemic infection or toxicity","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Surgery: other perirectal abscesses drained in the operating room; surgical excision of the fistula is definitive treatment and should not be delayed in ill-appearing patients"}]},"name":"Complicated perirectal abscess / ill-appearing / fistula","level":"II","imp":"Perirectal abscess (supralevator or ischiorectal) / fistula in ano","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۵۵ ساله دیابتی با تب، درد شدید لگن و توده عمقی ایسکیورکتال.","why":"آبسه‌های عمقی باید در اتاق عمل تخلیه شوند؛ بیمار بدحال بدون تأخیر جراحی می‌شود؛ NPO برای عمل.","esc":["شوک یا سپسیس، درد غیرمتناسب با معاینه یا کرپیتوس (فاشئیت نکروزان، فصل ۹۰)"]},{"id":"anorectal-pilonidal","o":{"I":[{"t":"Ultrasound to determine the extent of the abscess before incision and drainage"}],"T":[{"t":"Patient prone with buttocks retracted; appropriate sedation and local anesthesia; drain abscess, gently break loculations; pack the wound loosely with gauze and apply a bulky dressing"},{"t":"Sitz baths starting the following day"}],"A":[{"t":"Antibiotics and cultures","if":"immunocompromised patient or surrounding cellulitis","fl":[{"k":"note","v":"drug and dose not given in the book"}]}]},"name":"Pilonidal abscess","level":"III","imp":"Pilonidal abscess","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۲ ساله با توده دردناک و ترشح‌دار در شکاف بین باسن روی ساکروم.","why":"تخلیه در ED با بی‌حسی؛ آنتی‌بیوتیک فقط در ایمنوساپرس یا سلولیت اطراف."}],"ch":"47","name":"Anorectal abscess, fistula in ano, pilonidal sinus","name_fa":"آبسه آنورکتال، فیستول مقعدی و سینوس پیلونیدال","cc":["anorectal","fever"],"keywords":"perianal abscess, ischiorectal abscess, supralevator, fistula in ano, pilonidal abscess, incision and drainage, ciprofloxacin, metronidazole, آبسه پری‌آنال","status":"draft","features":["آبسه از کریپت‌های مقعد شروع می‌شود و پری‌آنال، اینترسفنکتریک، ایسکیورکتال یا فضای عمیق را درگیر می‌کند؛ آبسه پری‌آنال شایع‌ترین و در لبه مقعد است","درد گنگ، ضرباندار و پایدار که قبل از اجابت مزاج بیشتر می‌شود؛ با پیشرفت، نشستن و راه رفتن دردناک؛ تب، لکوسیتوز و توده دردناک در معاینه رکتال","عفونت‌های شدیدتر و تهدیدکننده حیات در بافت‌های عمیق (ایسکیورکتال، پلویورکتال) دیده می‌شود","فیستول: مسیر التهابی غیرطبیعی از غده مقعد عفونی؛ اغلب پس از آبسه؛ علل دیگر: Crohn، کولیت اولسراتیو، سل، پروکتیت گنوکوکی و کارسینوم؛ ترشح خونی بدبو مداوم","سونوگرافی اندوپروب 7 MHz با آب اکسیژنه 3٪ در تشخیص فیستول کمک می‌کند","سینوس پیلونیدال: در خط وسط بالای شکاف بین باسن روی ساکروم و کوکسیکس، واکنش گرانولومای جسم خارجی به مو؛ ممکن است کیست بدون درد، آبسه یا کیست مزمن با ترشح باشد؛ گاهی به اشتباه آبسه پری‌رکتال تشخیص داده می‌شود؛ سونوگرافی وسعت را پیش از برش نشان می‌دهد"],"ddx":[{"n":"Necrotizing soft tissue infection of perineum |","cm":1},{"n":"Deep supralevator / ischiorectal abscess |","cm":1},{"n":"Crohn disease |"},{"n":"Pilonidal abscess vs perirectal abscess |"},{"n":"Gonococcal proctitis / tuberculosis / carcinoma (fistula) |"}],"redflags":["تب و سمیت سیستمیک، بیمار ایمنوساپرس یا دیابتی، درد شدید با درگیری فضای عمیق (باید در اتاق عمل تخلیه شود)"],"guide":"آبسه ساده پری‌آنال بدون بیماری سیستمیک در ED با بی‌حسی کافی موضعی و ضددرد سیستمیک تخلیه می‌شود: برش صلیبی (cruciate) روی آبسه و برداشتن dog ears؛ معمولاً پک لازم نیست؛ سیتز از روز بعد. سایر آبسه‌های پری‌رکتال (supralevator و ischiorectal) در اتاق عمل. آنتی‌بیوتیک معمولاً لازم نیست مگر عفونت سیستمیک یا سمیت.\n\nفیستول: بیمار غیرسمی با ضددرد، تب‌بر و آنتی‌بیوتیک خوراکی؛ سیتز و تمیزکردن موضعی تا زمان جراحی؛ برش جراحی قطعی نباید در بیمار بدحال به تأخیر بیفتد.\n\nپیلونیدال: بیمار prone، تخلیه و شکستن لوکولاسیون‌ها، پک شل با گاز و پانسمان حجیم؛ سیتز از روز بعد؛ آنتی‌بیوتیک و کشت فقط در ایمنوساپرس یا سلولیت اطراف.","pearls":["پیلونیدال را با آبسه پری‌رکتال اشتباه نگیر؛ با نزدیکی به مقعد اشتباه رایج است."],"section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 47: Anorectal Disorders, pp. 265–272"},"proctitis-rectal-prolapse":{"id":"proctitis-rectal-prolapse","variants":[{"id":"proctitis-stable","o":{"L":[{"t":"Cultures if an infectious cause is suspected"}],"A":[{"t":"Antibiotics directed at the suspected underlying pathogen","if":"enteric pathogen or sexually transmitted infection","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Stool softeners, sitz baths, good anal hygiene and analgesics"}],"Co":[{"t":"Arrange outpatient follow-up"}]},"name":"Proctitis, stable","level":"III","imp":"Proctitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۳۰ ساله با درد و ترشح مقعد و اسهال خفیف.","why":"حمایتی، کشت در شک به عفونت و آنتی‌بیوتیک مختص پاتوژن."},{"id":"rectal-prolapse-reducible","o":{"T":[{"t":"Adult: generous amounts of granulated sugar applied 15 minutes before reduction, then reduction with direct, continuous pressure; tape lubricated gauze over the anal verge for a few hours after reduction"},{"t":"Child: gentle reduction under proper analgesia and sedation","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Refer to a specialist (child: to ensure the prolapse is not due to an underlying condition; prevent constipation)"}]},"name":"Rectal prolapse (adult or child), reducible","level":"III","imp":"Rectal prolapse","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۷۰ ساله با توده قرمز بیرون‌زده از مقعد و ترشح مخاطی.","why":"جا انداختن در ED با شکر؛ در کودک با سداسیون؛ ارجاع برای علت زمینه‌ای."},{"id":"rectal-prolapse-irreducible","o":{"T":[{"t":"Analgesia","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Emergency surgical consultation and hospitalization (if the prolapse cannot be easily reduced or there is evidence of ischemia)"}]},"name":"Rectal prolapse, irreducible or ischemic","level":"II","imp":"Rectal prolapse with possible ischemia","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مردی ۷۵ ساله با پرولاپس سیاه‌رنگ و غیرقابل جا انداختن.","why":"ایسکمی یا عدم موفقیت جا انداختن نیاز به جراحی اورژانس و بستری دارد."}],"ch":"47","name":"Proctitis, rectal prolapse, anorectal tumors","name_fa":"پروکتیت، پرولاپس رکتوم و تومورهای آنورکتال","cc":["anorectal","gi-bleeding"],"keywords":"proctitis, rectal prolapse, procidentia, sugar technique, anorectal tumor, anal cancer, sexually transmitted infection, پرولاپس رکتوم","status":"draft","features":["پروکتیت: التهاب مخاط رکتوم؛ علل: پرتودرمانی قبلی، اختلالات خودایمنی، واسکولیت، ایسکمی، عفونت‌های آمیزشی (سیفلیس، گنوره، کلامیدیا، LGV، هرپس، شانکروئید، HPV) و سایر عفونت‌ها","علائم پروکتیت: درد آنورکتال، خارش، ترشح، اسهال، خونریزی و کرامپ تحتانی شکم؛ در آنوسکوپی التهاب، اریتم، زخم یا ترشح","پرولاپس رکتوم: ناقص (فقط مخاط، چند سانتی‌متر از خط دندانه‌ای) یا کامل (همه لایه‌ها، توده قرمز گلوله‌ای تا 15 cm)؛ ترشح مخاطی، خونریزی و خارش؛ درد معمولاً شاخص نیست","اینتوساسپشن رکتوم ممکن است به شکل پرولاپس ظاهر شود","تومور آنورکتال: سیگار، رابطه مقعدی، HIV و زگیل تناسلی؛ آدنوکارسینوم، ملانوم بدخیم، سارکوم کاپوزی؛ علائم غیراختصاصی (توده، خارش، درد، خون)؛ بعداً یبوست، بی‌اشتهایی، کاهش وزن، باریک شدن قطر مدفوع و تنسموس؛ زخم غیربهبودیابنده حاشیه مقعد","عوارض تومور: پرولاپس رکتوم، خونریزی طولانی، آبسه پری‌رکتال و فیستول"],"ddx":[{"n":"Ischemic proctitis |","cm":1},{"n":"Anorectal malignancy |","cm":1},{"n":"Inflammatory bowel disease |"},{"n":"Hemorrhoids / anal fissure |"},{"n":"Rectal foreign body |"}],"redflags":["پرولاپس غیرقابل جا انداختن یا نشانه ایسکمی (نیاز به جراحی اورژانس)","زخم غیربهبودیابنده، کاهش وزن، باریک شدن مدفوع (بدخیمی)"],"guide":"# پروکتیت\nدر صورت شک به عفونت کشت بگیر؛ نرم‌کننده مدفوع، سیتز، بهداشت مقعد و ضددرد؛ آنتی‌بیوتیک مختص پاتوژن روده‌ای یا آمیزشی؛ پیگیری سرپایی.\n\n# پرولاپس رکتوم\nکودکان: جا انداختن ملایم با ضددرد و سداسیون مناسب سپس ارجاع به متخصص برای رد علت زمینه‌ای؛ جلوگیری از یبوست. بزرگسالان: اگر ادم دیواره جا انداختن را سخت کند، مقدار زیادی شکر دانه‌ای ۱۵ دقیقه قبل از جا انداختن با فشار مستقیم و مداوم؛ گاز لغزنده (lubricated) تا چند ساعت روی مقعد چسبانده شود. اگر به‌راحتی جا نرفت یا ایسکمی: مشاوره فوری جراحی و بستری.\n\n# تومورها\nدر شک بالینی: ارجاع برای پروکتوسکوپی/سیگموئیدوسکوپی و بیوپسی.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 47: Anorectal Disorders, pp. 265–272"},"rectal-foreign-body":{"id":"rectal-foreign-body","variants":[{"id":"rectal-fb-low","o":{"I":[{"t":"Abdominal and pelvis x-rays to demonstrate position, shape and number of foreign bodies"},{"t":"Upright film or CT scan for radiolucent foreign body and free air (perforation)"}],"T":[{"t":"Procedural sedation with perianal and submucosal analgesia; local infiltration anesthesia via 30-gauge needle into the internal sphincter muscle circumferentially for sphincter relaxation"},{"t":"Anal lubrication, obstetric forceps, speculum or snares, and patient bearing down"},{"t":"pass a catheter around the foreign body into the ampulla and inject air","if":"large bulbar object with vacuum effect"},{"t":"Foley catheter passed proximal to the foreign body, balloon inflated, gentle traction"},{"t":"Reevaluate anus and rectum after removal for lacerations and perforation"}],"Co":[{"t":"Surgical consultation (glass, sharp edges, high-lying, or removal not possible in the ED)"}]},"name":"Rectal foreign body (low-lying, no perforation)","level":"II","imp":"Rectal foreign body","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مردی ۴۰ ساله با جسم خارجی داخل رکتوم و درد خفیف شکم.","why":"خروج در ED با سداسیون و ریلکسیشن اسفنکتر؛ NPO برای سداسیون و احتمال عمل."}],"ch":"47","name":"Rectal foreign body","name_fa":"جسم خارجی رکتوم","cc":["anorectal","abdominal-pain"],"keywords":"rectal foreign body, retained object, vacuum effect, Foley, obstetric forceps, perforation, جسم خارجی رکتوم","status":"draft","features":["همه بیماران تاریخچه درست نمی‌دهند؛ ممکن است با درد شکم، خونریزی آنورکتال یا ترشح مراجعه کنند","بیشتر اجسام در آمپول رکتوم‌اند و در معاینه دیجیتال و پروکتوسکوپی لمس می‌شوند","رادیوگرافی شکم و لگن برای موقعیت، شکل و تعداد؛ فیلم upright یا CT برای جسم رادیولوسنت و هوای آزاد (سوراخ‌شدگی)"],"ddx":[{"n":"Rectal or colonic perforation |","cm":1},{"n":"Anorectal laceration / hemorrhage |"},{"n":"Peritonitis |"}],"redflags":["درد شکم، هوای آزاد در تصویربرداری، اجسام شیشه‌ای یا تیز"],"guide":"اجسام کم‌ارتفاع را می‌توان در ED خارج کرد؛ بسیاری نیاز به مشاوره و مداخله جراحی دارند (شیشه یا لبه تیز). سداسیون پروسیجرال همراه با بی‌حسی اطراف مقعد و زیر مخاط؛ ریلکسیشن اسفنکتر ضروری است: تزریق بی‌حسی موضعی با سوزن 30 gauge دور تا دور عضله اسفنکتر داخلی. روان‌کننده، فورسپس مامایی، اسپکولوم یا اسنار و زور زدن بیمار کمک می‌کنند. اجسام بزرگ بولبی اثر خلأ ایجاد می‌کنند: کاتتر را دور جسم عبور داده و هوا تزریق کن. گاهی عبور Foley از بالای جسم، باد کردن بالون و کشش ملایم کمک می‌کند. بعد از خروج، رکتوم و مقعد را برای پارگی و سوراخ‌شدگی دوباره ارزیابی کن.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 47: Anorectal Disorders, pp. 265–272"},"jaundice":{"id":"jaundice","variants":[{"id":"jaundice-stable","o":{"I":[{"t":"Ultrasonogram of the liver, biliary tract and pancreas (obstructive cause, mass or tumor)"}],"L":[{"t":"Serum bilirubin total and direct, AST, ALT, ALP, urinalysis (bilirubin and urobilinogen)"},{"t":"Additional tests according to clinical features: lipase or amylase, PT, glucose, GGT, albumin, viral hepatitis panel, drug levels, pregnancy test"}],"S":[{"t":"@fluid","if":"dehydrated and tachycardic"}],"Co":[{"t":"Outpatient follow-up (hemodynamically stable, no hepatic failure or acute biliary obstruction, reliable follow-up and adequate social support)"}]},"name":"Jaundice, stable (no hepatic failure or acute biliary obstruction)","level":"III","imp":"Jaundice","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۳۸ ساله با زردی خفیف و بدون تب یا درد، علائم حیاتی پایدار.","why":"بررسی اولیه در ED و ادامه کار سرپایی در بیمار پایدار با پیگیری مطمئن و حمایت اجتماعی."},{"id":"jaundice-obstructive-cholangitis","o":{"I":[{"t":"Ultrasonogram of the liver, biliary tract and pancreas; CT for pancreatic or intra-abdominal tumors"}],"L":[{"t":"Serum bilirubin total and direct, AST, ALT, ALP, lipase or amylase, PT, glucose, albumin, urinalysis"}],"S":[{"t":"Isotonic IV fluid therapy if dehydrated"}],"A":[{"t":"IV antibiotics (septic shock may develop expeditiously in ascending cholangitis)","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Admit extrahepatic obstructive jaundice for drainage (gastroenterology / surgery)"}]},"name":"Obstructive jaundice / suspected ascending cholangitis","level":"I","imp":"Obstructive jaundice with possible ascending cholangitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"زنی ۶۵ ساله با زردی، تب، درد RUQ و فشار 85/50.","why":"کولانژیت صعودی به‌سرعت به شوک سپتیک می‌رود؛ آنتی‌بیوتیک وریدی زودهنگام و درناژ."}],"ch":"48","name":"Jaundice","name_fa":"ایکتر (زردی)","cc":["jaundice"],"keywords":"jaundice, hyperbilirubinemia, conjugated, unconjugated, Gilbert, hemolysis, cholestasis, ALP, GGT, ascending cholangitis, ایکتر","status":"draft","features":["زردی پوست، صلبیه و مخاط به‌دلیل بیلی‌روبین بالا؛ معمولاً در سطح > 2.5 mg/dL آشکار می‌شود؛ علل: افزایش تولید (همولیز)، پردازش ناکافی سلولی (عفونت، دارو، سم)، کاهش دفع (تومور پانکراس، سنگ مجرای مشترک)","تقسیم‌بندی: پره‌هپاتیک، هپاتیک و پست‌هپاتیک؛ غیرکونژوگه (تولید زیاد یا اختلال کونژوگاسیون) و کونژوگه (کلستاز داخل یا خارج کبدی)","هپاتیت حاد در جوان سالم: شروع ناگهانی زردی با پرودروم تب، ضعف، تهوع، استفراغ و درد RUQ؛ بیماری الکلی و سیروز: شروع تدریجی","پیرها با بی‌اشتهایی، کاهش وزن و زردی بدون درد: بدخیمی هپاتوبیلیر یا پانکراس؛ متاستاز کبدی: کبد بزرگ، سخت، ندولار و دردناک","بیماری‌های ارثی (Gilbert، کمبود G6PD) با سابقه فامیلی یا زردی خفیف راجعه","سنگ مجرای مشترک، سابقه جراحی صفراوی، پانکراتیت، کولانژیت یا IBD (تنگی)؛ احتقان کبدی در نارسایی قلبی (هپاتومگالی، ادم پا، JVD، گالوپ)","شرح حال و معاینه و آزمایش‌های معمول در 85٪ بیماران به تشخیص دقیق می‌رسد"],"ddx":[{"n":"Ascending cholangitis |","cm":1},{"n":"Acute hepatitis / fulminant hepatic failure |","cm":1},{"n":"Hepatobiliary or pancreatic malignancy |","cm":1},{"n":"Hemolysis / hemoglobinopathy |"},{"n":"Gilbert syndrome / G6PD deficiency |"},{"n":"Passive hepatic congestion or ischemic hepatitis (heart failure) |"}],"redflags":["تب، ایکتر و درد RUQ یا شوک (کولانژیت)؛ تغییر هوشیاری، خونریزی یا اختلال انعقادی (نارسایی کبد)"],"guide":"تست‌های اولیه: بیلی‌روبین توتال و دایرکت (ایندایرکت با تفریق)، ترانس‌آمینازها، ALP، CBC و آنالیز ادرار (بیلی‌روبین و اوروبیلینوژن). بر اساس بالین: لیپاز یا آمیلاز، PT، الکترولیت و گلوکز، BUN و کراتینین، GGT، آلبومین، پانل هپاتیت ویروسی، سطح دارو، تست حاملگی.\n- بیلی‌روبین توتال و ایندایرکت بالا: تولید زیاد یا آسیب هپاتوسیت؛ توتال و دایرکت بالا: انسداد دفع.\n- ترانس‌آمیناز نرمال با زردی: سپسیس، حاملگی یا خطای متابولیک؛ همراه با کم‌خونی: همولیز (Coombs، الکتروفورز هموگلوبین).\n- ALP بالا: انسداد صفراوی و کلستاز؛ GGT: الکل و دارو.\n- سونوگرافی کبد، مجاری صفراوی و پانکراس برای علت انسدادی یا توده؛ CT برای تومورهای پانکراس و داخل شکم برتر است.\n\nدرمان بر اساس علت؛ عمدتاً حمایتی؛ کریستالوئید ایزوتونیک در دهیدراتاسیون؛ آنتی‌بیوتیک وریدی (شوک سپتیک در کولانژیت صعودی سریع رخ می‌دهد)؛ ایکتر انسدادی خارج کبدی بدون کولانژیت: بستری برای درناژ. بیمار پایدار بدون نارسایی کبد یا انسداد حاد صفراوی و قابل پیگیری: سرپایی.","section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 48: Jaundice, Hepatic Disorders, and Hepatic Failure, pp. 273–281"},"acute-hepatitis":{"id":"acute-hepatitis","variants":[{"id":"hepatitis-viral-outpatient","o":{"L":[{"t":"AST, ALT, ALP, total and direct bilirubin, PT/INR, albumin, glucose, viral hepatitis serologies (IgM anti-HAV, HBsAg, anti-HCV), serum acetaminophen level if toxic ingestion suspected"}],"S":[{"t":"@fluid","if":"dehydrated and tachycardic"}],"T":[{"t":"Pain management and antiemetic medication","fl":[{"k":"note","v":"drugs and doses not given in the book"}]},{"t":"Rest, adequate oral intake, strict personal hygiene, avoid hepatotoxins"}],"Co":[{"t":"Arrange follow-up; return to the ED for poor oral intake or worsening vomiting, jaundice or abdominal pain"}]},"name":"Acute viral hepatitis, stable","level":"III","imp":"Acute viral hepatitis","cond":"Urgent","act":"RBR","diet":"PO","ecg":"none","cxr":"none","sc":"مردی ۲۸ ساله با تهوع، ایکتر، ادرار تیره و درد RUQ؛ پایدار، قادر به نوشیدن.","why":"بیشتر هپاتیت ویروسی حاد نیاز به بستری ندارد؛ حمایتی و بازگشت در صورت بدتر شدن."},{"id":"hepatitis-alcoholic","o":{"L":[{"t":"AST, ALT, ALP, GGT, total and direct bilirubin, PT/INR, albumin, glucose"}],"S":[{"t":"Thiamine, magnesium, potassium and folate supplementation","fl":[{"k":"note","v":"doses not given in the book"}]},{"t":"@fluid","if":"dehydrated and tachycardic"}],"T":[{"t":"Prophylactic treatment for alcohol withdrawal if admission is required","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Advise to avoid further alcohol ingestion and hepatotoxins"}],"Co":[{"t":"Refer patient and family for detoxification or alcohol-dependency treatment"}]},"name":"Alcoholic hepatitis","level":"II","imp":"Acute alcoholic hepatitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مردی ۴۸ ساله با سابقه الکل مزمن، ایکتر، تب و درد شکم؛ AST دو برابر ALT.","why":"حمایتی؛ تغذیه و پرهیز؛ پروفیلاکسی ترک در بستری‌ها."},{"id":"hepatitis-fulminant","o":{"L":[{"t":"AST, ALT, bilirubin, PT/INR, albumin, ammonia, glucose, BUN, creatinine, electrolytes, serum acetaminophen level"}],"S":[{"t":"1 ampule D50W IV if hypoglycemia"}],"T":[{"t":"Aggressive support of circulation and respiration; monitor and treat increased intracranial pressure if present"},{"t":"Correct coagulopathy"},{"t":"Oral lactulose, oral aminoglycoside antibiotic (neomycin, vancomycin), significant protein restriction"}],"Co":[{"t":"Intensive care unit admission; early consultation with hepatologist and liver transplant service"}]},"name":"Fulminant hepatic failure","level":"I","imp":"Fulminant hepatic failure","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"زنی ۲۵ ساله با زردی، گیجی، خونریزی لثه و PT طولانی بعد از مصرف دارو.","why":"نیاز به مراقبت ویژه، درمان ICP و کواگولوپاتی و مشاوره زودهنگام پیوند."}],"ch":"48","name":"Acute hepatitis (viral, alcoholic) and fulminant hepatic failure","name_fa":"هپاتیت حاد (ویروسی، الکلی) و نارسایی فولمینانت کبد","cc":["jaundice","abdominal-pain","nausea-vomiting","altered-mental-status"],"keywords":"hepatitis A, hepatitis B, hepatitis C, alcoholic hepatitis, fulminant hepatic failure, acetaminophen, AST ALT, lactulose, neomycin, هپاتیت","status":"draft","features":["هپاتیت: التهاب کبد ناشی از آسیب عفونی، سمی یا متابولیک؛ شایع‌ترین علل: عفونت ویروسی و مصرف سم؛ طیف از بی‌علامت تا نارسایی فولمینانت و سیروز","علائم: تهوع، استفراغ و درد RUQ؛ تب، اسهال، ایکتر، بیلی‌روبینوری (ادرار تیره)، مدفوع رنگ‌پریده و کبد بزرگ و دردناک","تغییر هوشیاری، خونریزی غیرطبیعی (کبودی، خونریزی لثه، اپیستاکسی، مدفوع خونی)، آسیت و ادم پا: بیماری مزمن یا نارسایی فولمینانت","شرح حال: استامینوفن (دوز واحد یا مزمن بالا)، قارچ، صدف خام، داروهای گیاهی؛ تزریق خون، HIV، تزریق مواد، الکل مزمن، رفتار پرخطر، سفر","A: مدفوعی-دهانی؛ B: جنسی، خون، سوزن آلوده و پری‌ناتال؛ C: خون آلوده؛ B و C می‌توانند به عفونت مزمن، سیروز و HCC برسند؛ D، E، CMV، HSV، کوکساکی و EBV","سموم: استامینوفن، الکل، داروها (برخی آنتی‌بیوتیک‌ها، استاتین، ایزونیازید)، گیاهان (black cohosh، chaparral، Echinacea، kava) و مکمل‌ها","هپاتیت الکلی: بی‌اشتهایی، تهوع، تب، ادرار تیره، ایکتر، کاهش وزن، درد شکم و ضعف؛ AST > ALT (کمتر از 5 برابر نرمال؛ چند صد واحد)","نارسایی فولمینانت: بروز انسفالوپاتی ظرف 8 هفته از شروع علائم در کبد قبلاً سالم؛ ادم مغزی، ایکتر، آسیت، تندرنس RUQ و کواگولوپاتی"],"ddx":[{"n":"Acetaminophen toxicity |","cm":1},{"n":"Fulminant hepatic failure |","cm":1},{"n":"Viral, drug or toxin-induced, alcoholic or autoimmune hepatitis |"},{"n":"Cholecystitis and cholangitis |"},{"n":"HELLP syndrome |"},{"n":"Hepatic, pancreatic or biliary tumors / metastatic liver disease |"}],"redflags":["انسفالوپاتی، کواگولوپاتی، هیپوگلیسمی، بیلی‌روبین ≥ 20 mg/dL، PT بیش از 50٪ بالاتر از نرمال"],"guide":"# آزمایش‌ها\n- ترانس‌آمینازها: صدها = آسیب خفیف؛ هزاران = نکروز وسیع؛ ALT اختصاصی‌تر از AST؛ AST/ALT > 2 و GGT بالا: الکل.\n- ALP > 4 برابر: کلستاز.\n- گلوکز فوری در تغییر هوشیاری (هیپوگلیسمی)؛ الکترولیت، BUN و کراتینین (دهیدراتاسیون)؛ آمونیاک بالا و PT/INR (معیار واقعی عملکرد کبد) و آلبومین پایین: پیش‌آگهی بد.\n- سرولوژی: IgM anti-HAV برای A؛ HBsAg برای B؛ anti-HCV برای C (تاخیر 6 تا 8 هفته).\n- سطح استامینوفن پایه تشخیص و درمان در شک به مسمومیت.\n\n# درمان\nحمایتی (به جز استامینوفن، فصل ۱۰۶): ضددرد، ضدتهوع، مایع. هیپوگلیسمی: یک آمپول D50W IV. بستری: سالمند، حاملگی، اختلال مایع/الکترولیت، استفراغ مقاوم، بیلی‌روبین ≥ 20، PT بیش از 50٪ بالا، هیپوگلیسمی، آلبومین پایین، خونریزی گوارشی، انسفالوپاتی، ایمنوساپرسیون، شک به هپاتیت سمی. هپاتیت ویروسی حاد: سرپایی با استراحت، دریافت خوراکی کافی، بهداشت و پرهیز از سموم کبدی؛ بازگشت در صورت بدتر شدن.\n\nهپاتیت الکلی: حمایتی؛ تغذیه با تیامین، منیزیم، پتاسیم و فولات؛ پرهیز از الکل و سموم کبدی؛ ارجاع برای ترک؛ پروفیلاکسی ترک الکل در بیماران بستری.\n\nنارسایی فولمینانت: مراقبت ویژه در ED و ICU؛ حمایت تنفس و گردش خون، درمان افزایش ICP، اصلاح هیپوگلیسمی و کواگولوپاتی؛ لاکتولوز خوراکی، آنتی‌بیوتیک خوراکی آمینوگلیکوزید (neomycin، vancomycin) و محدودیت شدید پروتئین؛ مشاوره زودهنگام هپاتولوژی و پیوند.","pearls":["AST/ALT > 2 و GGT بالا = الکل.","بیمار مبتلا به تغییر هوشیاری: اول قند خون."],"section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 48: Jaundice, Hepatic Disorders, and Hepatic Failure, pp. 273–281"},"cirrhosis-complications":{"id":"cirrhosis-complications","variants":[{"id":"cirrhosis-ascites-mild","o":{"I":[{"t":"Bedside ultrasound to identify ascites and guide paracentesis"}],"L":[{"t":"AST, ALT, ALP, total and direct bilirubin, albumin, glucose, PT/INR, LDH, ammonia"}],"T":[{"t":"Salt-restricted diet; spironolactone 50 to 200 mg/d and amiloride 5 to 10 mg/d","fl":[{"k":"ci","v":"avoid furosemide as the main diuretic (overdiuresis); fluid restriction only if serum sodium < 120 to 125 mEq/L"}]}],"Co":[{"t":"Outpatient follow-up (no signs of infection or other complications)"}]},"name":"Cirrhosis with mild to moderate ascites, no complications","level":"III","imp":"Cirrhosis with ascites","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۵۸ ساله با سیروز الکلی، شکم برآمده و ادم پا؛ بدون تب یا درد.","why":"در نبود نشانه عفونت یا عارضه، سرپایی با رژیم کم‌نمک و دیورتیک."},{"id":"cirrhosis-large-ascites-paracentesis","o":{"I":[{"t":"Bedside ultrasound to guide paracentesis"}],"L":[{"t":"Ascitic fluid (50 cc): cell count, glucose, protein, Gram stain and culture (10 mL in a blood culture bottle at the bedside); AST, ALT, ALP, total and direct bilirubin, albumin, glucose, PT/INR, ammonia"}],"T":[{"t":"Therapeutic paracentesis; removal of more than 1 L can cause hypotension so close monitoring is necessary"},{"t":"Albumin 6 to 8 per L of fluid removed, for amounts greater than 4 L, to prevent fluid shift and intravascular collapse","fl":[{"k":"note","v":"unit printed as \"mg/L\" in the book, probably g per L of fluid removed"}]}],"Co":[{"t":"Admit if respiratory compromise, abdominal pain, fever, acidosis or leukocytosis; gastroenterology"}]},"name":"Large-volume ascites (therapeutic paracentesis)","level":"II","imp":"Cirrhosis with large-volume ascites","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۶۰ ساله با آسیت حجیم و تنگی نفس خفیف.","why":"پاراسنتز درمانی توصیه می‌شود؛ بیش از 1 L ممکن است افت فشار بدهد."},{"id":"cirrhosis-sbp","o":{"I":[{"t":"Bedside ultrasound for ascites and guide paracentesis; duplex Doppler for portal or hepatic vein thrombosis; abdominal CT for hepatic lesions"}],"L":[{"t":"Diagnostic paracentesis: ascitic fluid 50 cc for cell count, glucose, protein, Gram stain, culture (10 mL in blood culture bottle at the bedside); total WBC > 1000/mm3 or neutrophils > 250/mm3 = SBP"},{"t":"AST, ALT, ALP, total and direct bilirubin, LDH, albumin, ammonia, glucose, PT/INR"}],"A":[{"t":"Cefotaxime 2 g IV every 8 hours (first-line parenteral treatment)"},{"t":"Alternative: IV fluoroquinolone, except in patients who received prophylactic quinolone treatment","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Admit for SBP evaluation and treatment; hepatorenal syndrome often accompanies SBP"}]},"name":"Spontaneous bacterial peritonitis","level":"I","imp":"Spontaneous bacterial peritonitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۶۲ ساله با سیروز، آسیت، تب و درد شکم؛ مایع آسیت با نوتروفیل 600.","why":"SBP: نوتروفیل > 250 یا WBC > 1000؛ آنتی‌بیوتیک تجربی فوری و بستری."},{"id":"cirrhosis-hepatic-encephalopathy","o":{"I":[{"t":"Head CT to identify intracranial hemorrhage in patients with altered mental status"}],"L":[{"t":"Ammonia, glucose, BUN, creatinine, electrolytes, PT/INR, albumin, AST, ALT, ALP, bilirubin, LDH; diagnostic paracentesis if ascites","fl":[{"k":"note","v":"ammonia does not reliably correlate with mental status"}]}],"T":[{"t":"Lactulose 20 g PO diluted in a glass of water, fruit juice or carbonated drink"},{"t":"Lactulose enema: 300 mL of syrup in 700 mL of water or normal saline PR, retained for 30 minutes"},{"t":"Aggressively treat comorbidities (electrolyte abnormalities, hypoglycemia, ventilatory and circulatory dysfunction, sepsis, alcohol-related syndromes)"},{"t":"Avoid benzodiazepines","fl":[{"k":"ci","v":"avoid in cirrhosis"}]}],"Co":[{"t":"Admit (new or worsening hepatic encephalopathy); gastroenterology / liver transplant center if liver failure"}]},"name":"Hepatic encephalopathy (new or worsening)","level":"I","imp":"Hepatic encephalopathy","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۵۵ ساله با سیروز، گیجی و خواب‌آلودگی از دیروز؛ یبوست.","why":"لاکتولوز خط اصلی؛ علت تشدید (خونریزی، سپسیس، دارو) را پیدا و درمان کن؛ CT سر برای رد خونریزی."},{"id":"cirrhosis-coagulopathy-bleeding","o":{"L":[{"t":"PT/INR, albumin"}],"T":[{"t":"Vitamin K 10 mg PO or IV"},{"t":"Fresh frozen plasma in doses appropriate for patient's PT level"},{"t":"Pooled donor platelets for decreased or malfunctioning platelets"},{"t":"Specific treatments for variceal bleeding (see Chapter 39)"}],"Co":[{"t":"Gastroenterology; liver failure requires critical care in the ED and consultation with a gastroenterologist and a liver transplant center"}]},"name":"Cirrhosis with coagulopathy and bleeding","level":"I","imp":"Cirrhosis with coagulopathy and suspected gastroesophageal bleeding","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مرد ۵۰ ساله سیروزی با هماتمز و INR بالا.","why":"خونریزی با کواگولوپاتی نیاز به اصلاح دارد؛ واریس طبق فصل ۳۹."}],"ch":"48","name":"Cirrhosis: ascites, spontaneous bacterial peritonitis, hepatic encephalopathy","name_fa":"سیروز: آسیت، پریتونیت باکتریال خودبه‌خودی و انسفالوپاتی کبدی","cc":["abdominal-pain","altered-mental-status","leg-swelling","jaundice","fever"],"keywords":"cirrhosis, ascites, paracentesis, spontaneous bacterial peritonitis, SBP, hepatic encephalopathy, lactulose, spironolactone, hepatorenal syndrome, cefotaxime, سیروز, آسیت","status":"draft","features":["سیروز: جایگزینی پارانشیم کبد با فیبروز؛ علل: الکل، هپاتیت مزمن ویروسی؛ کمتر: دارو، همو‌کروماتوز، Wilson، سیروز صفراوی اولیه","علائم عمومی: خستگی، بی‌اشتهایی، ضعف، تحلیل عضلانی، تهوع، درد شکم، تب خفیف؛ دکمپانساسیون: آسیت، هپاتومگالی، انسفالوپاتی، ادم پا، ایکتر، خارش، اسپلنومگالی، آنژیوم عنکبوتی","آسیت علامت شاخص؛ می‌تواند دیافراگم را بالا برده و با پلورال افیوژن باعث اختلال تنفس شود","انسفالوپاتی کبدی: از خستگی مزمن یا گیجی خفیف تا خواب‌آلودگی حاد، هیپررفلکسی، اسپاستیسیته، تشنج و کما؛ تشدید با پروتئین زیاد، خونریزی گوارشی پنهان، یبوست، هیپو/هیپرگلیسمی، اختلال الکترولیت، ترک الکل، سپسیس، نارسایی کلیه، دارو","SBP: عارضه ظریف و مهم آسیت؛ تشخیص دشوار چون درد شکم و تب همیشه نیست و تندرنس ممکن است نباشد؛ شایع‌ترین ارگانیسم‌ها: Enterobacteriaceae مثل E. coli و Klebsiella (63٪) و S. pneumoniae (15٪)","سندرم هپاتورنال: نارسایی عملکردی کلیه در سیروز بدون بیماری ذاتی کلیه؛ اغلب همراه SBP","معمولاً با تشدید آسیت و ادم، تغییر هوشیاری، درد شکم، خونریزی گوارشی/واریس، پنومونی یا UTI مراجعه می‌کنند"],"ddx":[{"n":"Spontaneous bacterial peritonitis |","cm":1},{"n":"Gastroesophageal / variceal bleeding |","cm":1},{"n":"Intracranial hemorrhage (altered mental status) |","cm":1},{"n":"Hepatic encephalopathy vs hypoglycemia, sepsis, electrolyte imbalance |"},{"n":"Hepatorenal syndrome |"},{"n":"Portal or hepatic vein thrombosis / hepatocellular carcinoma |"}],"redflags":["تب، درد شکم، لکوسیتوز یا اسیدوز در آسیت (SBP)؛ هماتمز/ملنا؛ انسفالوپاتی تازه یا بدتر شونده؛ کواگولوپاتی همراه خونریزی"],"guide":"# آزمایش‌ها\nAST، ALT، ALP، بیلی‌روبین توتال و دایرکت، LDH، آلبومین، آمونیاک، گلوکز، BUN و کراتینین، الکترولیت، PT/INR، CBC؛ ترانس‌آمینازها در مرحله نهایی ممکن است نزدیک نرمال باشند؛ آمونیاک با سطح هوشیاری همبستگی قابل اتکا ندارد و علل دیگر تغییر هوشیاری را رد نمی‌کند.\n\n# پاراسنتز تشخیصی\nآسیت تازه‌تشخیص یا آسیت با تب، درد شکم، خونریزی گوارشی یا انسفالوپاتی: نمونه 50 cc برای شمارش سلولی، گلوکز، پروتئین، گرم و کشت؛ ۱۰ mL در بطری کشت خون کنار تخت. SBP: WBC > 1000/mm3 یا نوتروفیل > 250/mm3. سونوگرافی بالین برای آسیت و هدایت پاراسنتز؛ دوپلر برای ترومبوز ورید پورت و هپاتیک؛ CT سر در تغییر هوشیاری.\n\n# درمان\n- آسیت خفیف تا متوسط: رژیم کم‌نمک و دیورتیک سرپایی (spironolactone 50 تا 200 mg/d و amiloride 5 تا 10 mg/d)؛ فوروزماید مشکل‌ساز (دیورز بیش از حد)؛ محدودیت مایع فقط اگر Na < 120–125.\n- آسیت حجیم: پاراسنتز درمانی؛ برداشتن بیش از 1 L ممکن است افت فشار بدهد؛ بیش از 4 L: آلبومین 6 تا 8 (در کتاب «mg/L» چاپ شده؛ احتمالاً g به ازای هر لیتر مایع خارج‌شده) برای حجم بیش از 4 L.\n- SBP: آنتی‌بیوتیک تجربی؛ cefotaxime 2 g IV هر 8 ساعت خط اول؛ فلوروکینولون وریدی (مگر پروفیلاکسی کینولون)؛ خوراکی در موارد بسیار خفیف با پیگیری نزدیک.\n- انسفالوپاتی: لاکتولوز خط اصلی، خوراکی یا رکتال.\n- کواگولوپاتی: فقط اگر خونریزی کنترل‌نشده یا پروسیجر؛ ویتامین K 10 mg PO یا IV؛ FFP؛ پلاکت.\n- مسکن‌ها: NSAID پرهیز؛ استامینوفن حداکثر 2 g در روز؛ اپیوئید ممنوع در سابقه انسفالوپاتی یا سوءمصرف؛ فنتانیل و ترامادول با دوز کم و فاصله بیشتر در موارد منتخب؛ بنزودیازپین پرهیز؛ پروپوفول برای سداسیون کوتاه ایمن است.","pearls":["مایع آسیت را در هر آسیت تازه یا تب/درد/انسفالوپاتی بفرست؛ SBP شایع و خاموش است.","آمونیاک بالا جایگزین جستجوی علل دیگر تغییر هوشیاری نیست."],"section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 48: Jaundice, Hepatic Disorders, and Hepatic Failure, pp. 273–281"},"postoperative-complications":{"id":"postoperative-complications","variants":[{"id":"postop-fever-resp-uti","o":{"I":[{"t":"Chest x-ray; additional imaging like CT or ultrasound based on the operative procedure performed"}],"L":[{"t":"Urinalysis and urine culture"},{"t":"Evaluation focusing on the 5 Ws"}],"A":[{"t":"Antibiotic therapy covering nosocomial infections such as Pseudomonas and methicillin-resistant Staph aureus, with admission (see Chapter 30)","if":"postoperative pneumonia","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Oral antibiotic geared toward appropriate organisms; consider gram-positive flora if instrumentation occurred","if":"nontoxic UTI","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Pain control and increased deep breathing","if":"mild atelectasis without hypoxemia"}],"Co":[{"t":"Contact the surgeon who performed the procedure"}]},"name":"Postoperative fever: atelectasis / pneumonia / UTI","level":"II","imp":"Postoperative fever (atelectasis / pneumonia / UTI)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"PA","sc":"مردی ۶۵ ساله ۲ روز بعد از جراحی شکم با تب، تاکی‌پنه و درد پهلو.","why":"تب زودهنگام معمولاً تنفسی یا ادراری است؛ CXR و آنالیز ادرار.","esc":["هیپوکسمی، سمیت، بیمار سالمند یا بیماری مضعف: بستری"]},{"id":"postop-wound","o":{"T":[{"t":"Remove some sutures and evacuate; [seroma] needle aspiration","if":"wound hematoma"}],"A":[{"t":"Oral antibiotics","if":"wound infection without systemic toxicity or significant comorbidity","fl":[{"k":"note","v":"drug and dose not given in the book"}]},{"t":"Parenteral antibiotics (polymicrobial) with admission","if":"perineal infection","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Surgeon consultation before treating wound hematoma; operative exploration may be required for dehiscence"}]},"name":"Wound hematoma / seroma / infection / dehiscence","level":"II","imp":"Postoperative wound complication","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۵۰ ساله ۸ روز بعد از جراحی با قرمزی، تورم و ترشح زخم؛ تب خفیف.","why":"عفونت زخم روز 7 تا 10 است؛ بیمار غیرسمی با آنتی‌بیوتیک خوراکی؛ نشانه فاشئیت را بررسی کن."},{"id":"postop-necrotizing","o":{"A":[{"t":"Broad-spectrum parenteral antibiotics (see Chapter 90)","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Immediate surgical debridement"}]},"name":"Suspected necrotizing fasciitis / clostridial wound infection","level":"I","imp":"Necrotizing fasciitis (postoperative)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"once","cxr":"portable","sc":"مردی ۶۰ ساله دیابتی ۱ روز بعد از عمل با درد نامتناسب، گسترش سریع قرمزی و فشار 85/50.","why":"فاشئیت نکروزان: دبریدمان جراحی فوری و آنتی‌بیوتیک وسیع‌الطیف تزریقی (فصل ۹۰)."},{"id":"postop-ileus-intraabdominal","o":{"I":[{"t":"Abdominal imaging; CT or ultrasonography to confirm intra-abdominal abscess (upright chest or abdominal radiographs, CT most sensitive for colonoscopy perforation)"}],"L":[{"t":"Basic metabolic panel, urinalysis, lipase (more reliable than amylase)"}],"S":[{"t":"Intravenous hydration (bowel rest)"}],"A":[{"t":"Antibiotic therapy","if":"intra-abdominal abscess or anastomotic leak","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"Bowel rest, nasogastric suction"}],"Co":[{"t":"Surgery (obstruction due to adhesions, abscess drainage, anastomotic leak, fistula, perforation)"}]},"name":"Postoperative ileus / abscess / leak / pancreatitis after GI surgery","level":"II","imp":"Postoperative GI complication (ileus, intra-abdominal abscess, anastomotic leak)","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"PA","sc":"مردی ۷۰ ساله ۴ روز بعد از کولکتومی با تهوع، استفراغ، اتساع و درد شکم.","why":"ایلئوس طولانی نیاز به بررسی علل غیرعصبی دارد؛ NPO و NG و مایع."},{"id":"postop-thrombophlebitis-pmc","o":{"L":[{"t":"Stool C difficile cytotoxin (negative in 27% of cases)"}],"S":[{"t":"@fluid","if":"dehydrated and tachycardic","why":"fluid resuscitation for suspected PMC"}],"A":[{"t":"Metronidazole (oral or IV) and oral vancomycin","if":"suspected pseudomembranous colitis","fl":[{"k":"note","v":"dose not given in the book"}]},{"t":"Antibiotics","if":"superficial thrombophlebitis with cellulitis or lymphangitis","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"T":[{"t":"NSAIDs, local heat application and elevation","if":"superficial thrombophlebitis","fl":[{"k":"note","v":"drug and dose not given in the book"}]}],"Co":[{"t":"Suppurative thrombophlebitis: hospitalization and surgical excision"}]},"name":"Thrombophlebitis / antibiotic-induced pseudomembranous colitis","level":"III","imp":"Postoperative thrombophlebitis / pseudomembranous colitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زنی ۶۸ ساله با اسهال آبکی و تب بعد از دوره آنتی‌بیوتیک پس از جراحی.","why":"PMC با مایع و متروندازول/وانکومایسین؛ ترومبوفلبیت سطحی با NSAID و گرما."}],"ch":"49","name":"Complications of general surgical procedures (postoperative fever, wound, ileus, thrombophlebitis, pseudomembranous colitis)","name_fa":"عوارض پس از اعمال جراحی عمومی","cc":["fever","wound-bite","abdominal-pain","diarrhea"],"keywords":"postoperative fever, atelectasis, wound infection, hematoma, seroma, dehiscence, ileus, thrombophlebitis, pseudomembranous colitis, dumping syndrome, anastomotic leak, colonoscopy perforation, PEG tube, stoma, عوارض بعد از جراحی","status":"draft","features":["تب بعد از عمل (5 Ws): wind (تنفسی)، water (UTI)، wound (زخم)، walking (DVT)، wonder drugs (تب دارویی یا PMC)","تب در 24 ساعت اول: معمولاً آتلکتازی؛ در نظر داشتن فاشئیت نکروزان و کلستریدیال؛ 72 ساعت اول: پنومونی، آتلکتازی، ترومبوفلبیت کاتتر وریدی؛ UTI روز 1 تا 5؛ DVT از روز 5؛ عفونت زخم روز 7 تا 10؛ PMC تا 6 هفته بعد","آتلکتازی: تب، تاکی‌پنه، تاکی‌کاردی و هیپوکسی خفیف؛ پنومونی 24 تا 96 ساعت بعد (فصل ۳۰)؛ آمبولی ریه هر زمان (فصل ۲۵)","احتباس ادراری در مردان سالمند، جراحی آنورکتال یا طولانی و بی‌حسی نخاعی/اپیدورال (فصل ۵۴)؛ کاهش ادرار: نارسایی کلیه یا حجم کم (فصل ۵۰)","هماتوم (خونریزی ناکافی)؛ سروما (مایع شفاف زیر زخم)؛ عفونت زخم: درد، تورم، اریتم، ترشح؛ عوامل خطر: سن‌های حدی، دیابت، سوءتغذیه، بافت نکروتیک، خون‌رسانی ضعیف، جسم خارجی؛ فاشئیت نکروزان در بیمار بدحال با عفونت در حال گسترش و درد نامتناسب (فصل ۹۰)","دهیسانس سطحی یا عمقی فاشیا: دیابت، سوءتغذیه، استروئید مزمن، بستن نامناسب","ترومبوفلبیت سطحی: اریتم، گرما، پری ورید؛ بعد از کاتتر وریدی یا واریس؛ DVT بیشتر در پاها (فصل ۲۵)","PMC: سم Clostridium difficile؛ اسهال آبکی یا خونی، تب، کرامپ؛ آزمایش سیتوتوکسین ممکن است در 27٪ منفی باشد","ایلئوس بعد از جراحی گوارشی: روده کوچک ظرف 24 ساعت، کولون 3 تا 5 روز؛ طولانی بودن: پریتونیت، آبسه، خونریزی، پنومونی، سپسیس، الکترولیت، دارو","آبسه داخل شکم: آلودگی، نشت یا نشت آناستوموز (CT یا سونوگرافی)","پانکراتیت (لیپاز مطمئن‌تر)، کولسیستیت بدون سنگ در سالمندان، فیستول، نشت آناستوموز (ازوفاژ تا 10 روز با مرگ‌ومیر بالا)","جراحی چاقی: نشت و خونریزی در هفته‌های اول؛ دامپینگ (تهوع، استفراغ، درد اپی‌گاستر، تپش، سرگیجه، سنکوپ)","لاپاروسکوپی، لوله‌های تغذیه، استوما و کولونوسکوپی (خونریزی و سوراخ‌شدگی؛ CT حساس‌تر)"],"ddx":[{"n":"Necrotizing fasciitis / clostridial wound infection |","cm":1},{"n":"Pulmonary embolism / DVT |","cm":1},{"n":"Anastomotic leak / peritonitis / intra-abdominal abscess |","cm":1},{"n":"Atelectasis / pneumonia |"},{"n":"Urinary tract infection / urinary retention |"},{"n":"Drug fever / pseudomembranous colitis |"}],"redflags":["فاشئیت نکروزان (درد نامتناسب، سمیت)، نشت آناستوموز، سوراخ‌شدگی کولون، بیمار سمی یا بیماری زمینه‌ای مضعف یا سالمند"],"guide":"با جراحی که پروسیجر را انجام داده تماس بگیرید. بیمار سمی، با بیماری مضعف یا سالمند: بستری.\n1. آتلکتازی خفیف بدون هیپوکسمی: سرپایی با کنترل درد و تنفس عمیق.\n2. پنومونی بعد از عمل: چندمیکروبی؛ بستری و آنتی‌بیوتیک پوشش‌دهنده عفونت‌های بیمارستانی (Pseudomonas و MRSA) (فصل ۳۰).\n3. UTI غیرسمی: سرپایی با آنتی‌بیوتیک خوراکی؛ در دستکاری، فلور گرم‌مثبت؛ بدحال: بستری.\n4. هماتوم زخم: برداشتن بخیه‌ها و تخلیه؛ مشورت با جراح؛ سروما: آسپیراسیون با سوزن.\n5. عفونت زخم: آنتی‌بیوتیک خوراکی مگر سمیت یا بیماری زمینه‌ای؛ عفونت پرینه: چندمیکروبی، آنتی‌بیوتیک تزریقی و بستری؛ فاشئیت نکروزان: دبریدمان فوری و آنتی‌بیوتیک وسیع‌الطیف (فصل ۹۰).\n6. ترومبوفلبیت سطحی: سرپایی با NSAID، گرما و بالا نگه‌داشتن اندام؛ آنتی‌بیوتیک در سلولیت یا لنفانژیت؛ ترومبوفلبیت چرکی: بستری و برداشتن جراحی.\n7. PMC: مایع، درمان تجربی؛ metronidazole خوراکی یا وریدی و vancomycin خوراکی.","pearls":["در تب بعد از عمل به 5 Ws فکر کن و زمان بروز را با تشخیص تطبیق بده.","لوله PEG جابه‌جا شده با لوله هم‌اندازه جایگزین شود (در صورت نبود: Foley موقت)."],"section":"gastrointestinal","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 49: Complications of General Surgical Procedures, pp. 282–286"}});
